window.L5R_CHARACTER = {"slug":"doji-setsuna","name":"Doji Setsuna","clan":"Crane","family":"Doji","school":"Doji Bureaucrat School","role":"Courtier","bucket":null,"campaign":"The Fragile Peace","status":null,"accent":null,"portrait":"src/portraits/doji-setsuna.webp","concept":null,"summary":null,"tier_count":5,"xp_min":0,"xp_max":100,"twenty_questions":{"template":"core","generated":true,"steps":{"step1":{"answers":{"clan":"Crane","ring":"air","skill":"culture","social_status":35},"picks":{}},"step2":{"answers":{"family":"Doji","ring":"water","skill1":"courtesy","skill2":"design","wealth":8,"social_glory":44},"picks":{}},"step3":{"answers":{"school":"Doji Bureaucrat School","roles":"Courtier","ring1":"earth","ring2":"water","skill1":"composition","skill2":"courtesy","skill3":"government","skill4":"culture","skill5":"command","social_honor":55},"picks":{}},"step4":{"answers":{"stand_out":"She is a careful and close reader in imperial law, and often finds subtle and surprising interactions within it.","ring":"air"},"picks":{}},"step5":{"answers":{"social_giri":"Currently, Kitsuki Kāgi, in service as an Emerald Magistrate under the Emperor.\n\nPreviously, she served Asahina Shigehiro, lord of the city of Shirogome, on issues of imperial law and legal arbitration.\n\nHer giri: Rule must bind, and if needed, contort."},"picks":{}},"step6":{"answers":{"social_ninjo":"Strictures too often interfere with a beautiful tale.\n\nShe escapes into literature, particularly pillow-books, and riding her horse, Kogorashi, a Utaku steed and wedding gift from her husband's family."},"picks":{}},"step7":{"answers":{"clan_relations":"Positive, as she upholds Crane values, although her ruling put her at odds with a Kakita family daimyo.","skill":"command","social_add_glory":0},"picks":{}},"step8":{"answers":{"bushido":"Rigid acquiescence.","social_add_honor":10,"tenet_paramount":"Courtesy","tenet_less_significant":"Courage"},"picks":{}},"step9":{"answers":{"success":"She served Asahina Shigehiro, lord of the city of Shirogome, on issues of imperial law and legal arbitration. Her most notable moment was when there was a dispute with the provincial daimyo, a Kakita, who attempted to impose new levies on skilled artisans.\n\nShe ruled that artisans were protected under an Imperial precedent granting exemptions to craftsmen in service to samurai and the court, citing an edict from Hantei V, which specified examples (non-exclusive) or silk and ceramics which were essential to Imperial culture and could not be overtaxed. The daimyo backed down, knowing that pushing forward could invite scrutiny and a more binding decision from an emerald magistrate.\n\nThis situation resulted in both Affect of Harmlessness (Air) and Scorn of Kakita (Water)"},"picks":{}},"step10":{"answers":{"difficulty":"See question 9."},"picks":{}},"step11":{"answers":{"calms":"At peace when writing poetry and reading pillow books, as well as riding Kogorashi."},"picks":{}},"step12":{"answers":{"worries":"She is terrified of death."},"picks":{}},"step13":{"answers":{"most_learn":"Bayushi Tomono: A Scorpion courtier visiting Shirogome. Engaged in wordplay with Setsuna, and taught her how to exploit Imperial law and weaponize “harmlessness”.","skill":"composition"},"picks":{}},"step14":{"answers":{"first_sight":"The first thing people notice about Doji Setsuna is her manner of speech; not just its elegance, but its precision. She speaks in a way that feels deliberate, choosing less ordinary words when a specificity is needed. This can be delightful or discomforting. It also means that when she seems to misspeak, it may have been intentional.\n\nHer otherwise immaculate presentation is consistently marred by stray strands of hair escaping."},"picks":{}},"step15":{"answers":{"stress":"In times of stress, she will usually step forward into a situation, even one that feels dangerous or that she is woefully ill-equipped for, believing that her words might help de-escalate or escape the situation.\n\nWhen her strife is high, her need for agency rises, and she will try increasingly improbable solutions, and grow curt with people who impede her attempts to cut through to a solution.\n\nThe only people whose approval she cares about are Asahina Shigehiro, Bayushi Tomono, and Kitsuki Kāgi."},"picks":{}},"step16":{"answers":{"relations":"Kakita Noritomo: Does not openly acknowledge his disdain, but Setsuna has been barred from Kakita courts and dojos following her ruling.\n    - His allies within the Emerald Magistrates may look for opportunities to undermine or discredit her.\nShinjo Harunobu: A respected Shinjo commander. Respects Setsuna’s intellect, but prefers to solve problems directly and not through “legal trickery”. It was a political marriage but they barely speak beyond what is necessary, and Harunobu spends most of his time away on campaign. He sees little value in courtly games and is blind to how Setsuna protects him politically.\nDoji Masateru (Father): An imperial legal scholar, well versed, emotionally distant. Taught Setsuna to wield the law like a sword. A single correct argument, like a single cut, should be fatal.\nDoji Ayaka (Mother): The marriage to Takahiro was her working, and she cannot claim ignorance; a year after the marriage, she advised obliquely that a “daughter of the Doji turns infidelities into poetry.”\nDoji Retsuo (Older Brother): The model heir. Thinks she is too verbose.\nDoji Emika (Younger Sister): Sees Setsuna as a woman trapped by duty, but keeps her thoughts private, but has no desire to follow in her footsteps.\nEmerald Magistrate Mirumoto Kyou resents Setsuna; she does not seem to cherish her role that she bested him at. He does not understand how she was chosen over him.\nEmerald Magistrate Kakita Yoshitada did not support Setsuna’s appointment. Would never openly undermine an Emerald Magistrate. Two decades of experience in Imperial law and dueling arbitration."},"picks":{}},"step17":{"answers":{"parents_pov":"Doji Masateru (Father): An imperial legal scholar, well versed, emotionally distant. Taught Setsuna to wield the law like a sword. A single correct argument, like a single cut, should be fatal.\nDoji Ayaka (Mother): The marriage to Takahiro was her working, and she cannot claim ignorance; a year after the marriage, she advised obliquely that a “daughter of the Doji turns infidelities into poetry.”","skill":"sentiment"},"picks":{}},"step18":{"answers":{"heritage_name":"Named after her great-aunt, who perished nobly in battle. Estate was lost.","heritage_1":9,"heritage_add_status":10},"picks":{}},"step19":{"answers":{"firstname":"Setsuna"},"picks":{}},"step20":{"answers":{"death":"Setsuna should die unexpectedly and suddenly, so that she does not have a chance to shrink from it or overthink it. It is unlikely that her destiny is fulfilled in this life."},"picks":{}}}},"notes":"<p class=\"font-claude-response-body break-words whitespace-normal leading-[1.7]\"><strong>Kogarashi</strong> is a white Utaku steed with a silver mane and tail — lean, swift, and always poised. She was a wedding gift from the Shinjo family and is the one being in Setsuna's life to whom warmth flows without mediation. Ridden equally for pleasure and for political effect, Kogarashi's distinctive Utaku breeding marks Setsuna at distance to any Unicorn who sees her.</p><hr class=\"border-border-200 border-t-0.5 my-3 mx-1.5\"><p class=\"font-claude-response-body break-words whitespace-normal leading-[1.7]\">Setsuna currently serves Imperial Envoy Miya Misato as her Personal Advisor. Her <em>giri</em> is to see Misato succeed in brokering a peace between the Lion and the Unicorn. Her <em>ninjō</em> is to innovate the trilateral agreement for Toshi Ranbo — for the Crane clan, for her grandmother, and to see to her husband's freedom.</p><hr class=\"border-border-200 border-t-0.5 my-3 mx-1.5\"><p class=\"font-claude-response-body break-words whitespace-normal leading-[1.7]\"><strong>Household</strong></p><ul class=\"[li_&amp;]:mb-0 [li_&amp;]:mt-1 [li_&amp;]:gap-1 [&amp;:not(:last-child)_ul]:pb-1 [&amp;:not(:last-child)_ol]:pb-1 list-disc flex flex-col gap-1 pl-8 mb-3\"><li class=\"font-claude-response-body whitespace-normal break-words pl-2\"><strong>Aika</strong> — Personal attendant. Former geisha, now in Setsuna's intimate care. Manages hair, dress, and the chamber. Geisha-trained discretion. One of the two senior women of the household.</li><li class=\"font-claude-response-body whitespace-normal break-words pl-2\"><strong>Ishika</strong> — Lady's maid and personal attendant. Quiet, middle-aged, motherly. Carries the maternal-continuity register of the household. The second of the two senior women.</li><li class=\"font-claude-response-body whitespace-normal break-words pl-2\"><strong>Otoya</strong> — Scribe and legal assistant. A Crane man with encyclopedic knowledge of Imperial law. Setsuna's working partner for document preparation and legal research.</li><li class=\"font-claude-response-body whitespace-normal break-words pl-2\"><strong>Jiro</strong> — Horse attendant. A Unicorn, responsible for the care of Kogarashi.</li><li class=\"font-claude-response-body whitespace-normal break-words pl-2\"><strong>Bayushi Monbon</strong> — Yojimbo. A Scorpion samurai assigned to Setsuna as punishment duty by his lord, originally without the right of seppuku. Fired by Setsuna at the Ifrit incident and reclaimed at the Midnight Treaty; his ransom was invoiced back to his lord. Currently in functional partnership with her. Carries a bound Lady of Decay that has been growing in visibility.</li></ul><hr><p><strong>Family</strong></p><ul class=\"[li_&amp;]:mb-0 [li_&amp;]:mt-1 [li_&amp;]:gap-1 [&amp;:not(:last-child)_ul]:pb-1 [&amp;:not(:last-child)_ol]:pb-1 list-disc flex flex-col gap-1 pl-8 mb-3\"><li class=\"font-claude-response-body whitespace-normal break-words pl-2\"><strong>Doji Masateru</strong> — Father. Imperial legal scholar, well-versed and emotionally distant. Taught her to wield the law like a sword: a single correct argument, like a single cut, should be fatal.</li><li class=\"font-claude-response-body whitespace-normal break-words pl-2\"><strong>Doji Ayaka</strong> — Mother. Arranged her marriage to Harunobu. A year later, advised obliquely that <em>a daughter of the Doji turns infidelities into poetry</em>.</li><li class=\"font-claude-response-body whitespace-normal break-words pl-2\"><strong>Doji Retsuo</strong> — Older brother. The model heir. Thinks she is too verbose.</li><li class=\"font-claude-response-body whitespace-normal break-words pl-2\"><strong>Doji Emika</strong> — Younger sister. Sees Setsuna as a woman trapped by duty, but keeps her thoughts private. Has no desire to follow in her footsteps. Reserved in Setsuna's plans for the Toshi Ranbo settlement, to marry into the Matsu family and satisfy the grandmother's restoration demand.</li><li class=\"font-claude-response-body whitespace-normal break-words pl-2\"><strong>Matsu Tomoe</strong> — Late maternal grandmother. Married into the Crane from the Matsu and hated being a Crane for the rest of her life. Now haunts Setsuna as a ghost, demanding the restoration of Toshi Ranbo and the Matsu lineage.</li></ul><p class=\"font-claude-response-body break-words whitespace-normal leading-[1.7]\"><strong>Marriage</strong></p><ul class=\"[li_&amp;]:mb-0 [li_&amp;]:mt-1 [li_&amp;]:gap-1 [&amp;:not(:last-child)_ul]:pb-1 [&amp;:not(:last-child)_ol]:pb-1 list-disc flex flex-col gap-1 pl-8 mb-3\"><li class=\"font-claude-response-body whitespace-normal break-words pl-2\"><strong>Shinjo Harunobu</strong> — Husband. A respected Shinjo commander, currently a Lion prisoner of war. Loves her and respects her intellect, though he considers her work <em>legal trickery</em> and prefers to solve problems directly. He understands he has married up. They communicate by letter; the marriage has been long-distance for years.</li></ul><p class=\"font-claude-response-body break-words whitespace-normal leading-[1.7]\"><strong>Mentors and Superiors</strong></p><ul class=\"[li_&amp;]:mb-0 [li_&amp;]:mt-1 [li_&amp;]:gap-1 [&amp;:not(:last-child)_ul]:pb-1 [&amp;:not(:last-child)_ol]:pb-1 list-disc flex flex-col gap-1 pl-8 mb-3\"><li class=\"font-claude-response-body whitespace-normal break-words pl-2\"><strong>Bayushi Tomono</strong> — Scorpion courtier she encountered in Shirogome. Engaged her in wordplay and taught her how to exploit Imperial law and weaponize harmlessness. One of three people whose approval she cares about.</li><li class=\"font-claude-response-body whitespace-normal break-words pl-2\"><strong>Asahina Shigehiro</strong> — Her former lord, Crane shugenja and ruler of the city of Shirogome. Employed her as legal counsel on matters of Imperial law. One of three whose approval matters.</li><li class=\"font-claude-response-body whitespace-normal break-words pl-2\"><strong>Kitsuki Kāgi</strong> — Her Emerald Magistrate superior. Recruited her into Imperial service after the Kakita tax loophole brought her to his attention. One of three whose approval matters.</li></ul><p class=\"font-claude-response-body break-words whitespace-normal leading-[1.7]\"><strong>Magistrate Colleagues</strong></p><ul class=\"[li_&amp;]:mb-0 [li_&amp;]:mt-1 [li_&amp;]:gap-1 [&amp;:not(:last-child)_ul]:pb-1 [&amp;:not(:last-child)_ol]:pb-1 list-disc flex flex-col gap-1 pl-8 mb-3\"><li class=\"font-claude-response-body whitespace-normal break-words pl-2\"><strong>Kakita Kazumi</strong> — Kakita duelist, Topaz Champion, and trained Crane Harrier (shinobi) operating in plain sight. Has consistently shown her discretion and quiet loyalty, including providing logistical support during the abortion procedure.</li><li class=\"font-claude-response-body whitespace-normal break-words pl-2\"><strong>Shiba Midori</strong> — Phoenix shugenja. Brewed the abortifacient and conducted the procedure. The sole peer-level intimate with whom Setsuna has been visibly unmasked. Her shugenja presence first allowed the grandmother's ghost to manifest.</li></ul><p class=\"font-claude-response-body break-words whitespace-normal leading-[1.7]\"><strong>Lord</strong></p><ul class=\"[li_&amp;]:mb-0 [li_&amp;]:mt-1 [li_&amp;]:gap-1 [&amp;:not(:last-child)_ul]:pb-1 [&amp;:not(:last-child)_ol]:pb-1 list-disc flex flex-col gap-1 pl-8 mb-3\"><li class=\"font-claude-response-body whitespace-normal break-words pl-2\"><strong>Miya Misato</strong> — Imperial Envoy, sixteen years old. Originally dispatched on a mission designed to fail. Setsuna appointed herself as her advisor and has invested her own XP transferring skills to her. Nearly assassinated and now blind, but alive. The displaced object of the motherhood Setsuna refused, and simultaneously her operational frame and political instrument.</li></ul><p class=\"font-claude-response-body break-words whitespace-normal leading-[1.7]\"><strong>Adversary</strong></p><ul class=\"[li_&amp;]:mb-0 [li_&amp;]:mt-1 [li_&amp;]:gap-1 [&amp;:not(:last-child)_ul]:pb-1 [&amp;:not(:last-child)_ol]:pb-1 list-disc flex flex-col gap-1 pl-8 mb-3\"><li class=\"font-claude-response-body whitespace-normal break-words pl-2\"><strong>Kakita Noritomo</strong> — The Kakita provincial daimyō whose new artisan tax Setsuna voided through an Imperial precedent during her time in Shirogome. He banned her from his lands rather than risk a contest he would lose; the institutional grudge remains active in the Kakita family.</li></ul><p class=\"font-claude-response-body break-words whitespace-normal leading-[1.7]\"><strong>The Lover At Court</strong></p><ul class=\"[li_&amp;]:mb-0 [li_&amp;]:mt-1 [li_&amp;]:gap-1 [&amp;:not(:last-child)_ul]:pb-1 [&amp;:not(:last-child)_ol]:pb-1 list-disc flex flex-col gap-1 pl-8 mb-3\"><li class=\"font-claude-response-body whitespace-normal break-words pl-2\">An unnamed member of an Imperial family in Otosan Uchi. Father of the pregnancy Setsuna conceived approximately four months before her departure for Loyalty Castle. He does not know she was pregnant and has never known. Setsuna does not pursue contact.</li></ul>","bio":"","curriculum":[{"rank":1,"kind":"Skill Group","group":null,"label":"Scholar Skills","prereq":false},{"rank":1,"kind":"Skill","group":null,"label":"Commerce","prereq":false},{"rank":1,"kind":"Skill","group":null,"label":"Composition","prereq":false},{"rank":1,"kind":"Skill","group":null,"label":"Courtesy","prereq":false},{"rank":1,"kind":"Tech. Grp.","group":"shuji","label":"Rank 1 Earth Shūji","prereq":false},{"rank":1,"kind":"Technique","group":"ritual","label":"Treaty Signing","prereq":true},{"rank":1,"kind":"Technique","group":"shuji","label":"Beware The Smallest Mouse","prereq":false},{"rank":2,"kind":"Skill Group","group":null,"label":"Trade Skills","prereq":false},{"rank":2,"kind":"Skill","group":null,"label":"Courtesy","prereq":false},{"rank":2,"kind":"Skill","group":null,"label":"Games","prereq":false},{"rank":2,"kind":"Skill","group":null,"label":"Government","prereq":false},{"rank":2,"kind":"Tech. Grp.","group":"shuji","label":"Rank 1-2 Water Shūji","prereq":false},{"rank":2,"kind":"Technique","group":"shuji","label":"The Wind Blows Both Ways","prereq":true},{"rank":2,"kind":"Technique","group":"shuji","label":"Unyielding Terms","prereq":false},{"rank":3,"kind":"Skill Group","group":null,"label":"Social Skills","prereq":false},{"rank":3,"kind":"Skill","group":null,"label":"Commerce","prereq":false},{"rank":3,"kind":"Skill","group":null,"label":"Culture","prereq":false},{"rank":3,"kind":"Skill","group":null,"label":"Sentiment","prereq":false},{"rank":3,"kind":"Tech. Grp.","group":"shuji","label":"Rank 1-3 Air Shūji","prereq":false},{"rank":3,"kind":"Technique","group":"shuji","label":"Hidden in Smoke","prereq":true},{"rank":3,"kind":"Technique","group":"shuji","label":"All Shall Fear Me","prereq":false},{"rank":4,"kind":"Skill Group","group":null,"label":"Scholar Skills","prereq":false},{"rank":4,"kind":"Skill","group":null,"label":"Command","prereq":false},{"rank":4,"kind":"Skill","group":null,"label":"Meditation","prereq":false},{"rank":4,"kind":"Skill","group":null,"label":"Tactics","prereq":false},{"rank":4,"kind":"Tech. Grp.","group":"ritual","label":"Rank 1-4 Rituals","prereq":false},{"rank":4,"kind":"Technique","group":"shuji","label":"The Immovable Hand of Peace","prereq":true},{"rank":4,"kind":"Technique","group":"shuji","label":"Rallying Cry","prereq":false},{"rank":5,"kind":"Skill Group","group":null,"label":"Trade Skills","prereq":false},{"rank":5,"kind":"Skills","group":null,"label":"Command","prereq":false},{"rank":5,"kind":"Skill","group":null,"label":"Performance","prereq":false},{"rank":5,"kind":"Skill","group":null,"label":"Tactics","prereq":false},{"rank":5,"kind":"Tech. Grp.","group":"shuji","label":"Rank 1-5 Void Shūji","prereq":false},{"rank":5,"kind":"Technique","group":"shuji","label":"Bend with the Storm","prereq":false},{"rank":5,"kind":"Technique","group":"ritual","label":"Formal Tea Ceremony","prereq":false}],"title_curricula":{"personaladvisortomiyamisato":{"title":"Advisor","aliased_from":"Advisor","ability":"Skilled Attendant","status_award":"+10 (to a minimum of 40)","entries":[{"kind":"Skill Group","group":null,"label":"Scholar Skills","prereq":false},{"kind":"Skill","group":null,"label":"Commerce","prereq":false},{"kind":"Skill","group":null,"label":"Courtesy","prereq":false},{"kind":"Skill","group":null,"label":"Design","prereq":false},{"kind":"Technique","group":"shuji","label":"Fanning the Flames","prereq":true},{"kind":"Technique","group":"shuji","label":"Feigned Opening","prereq":true},{"kind":"Technique","group":"shuji","label":"Stonewall Tactics","prereq":true}]},"emeraldmagistrate":{"title":"Emerald Magistrate","aliased_from":null,"ability":"Voice of Authority","status_award":"+15 (to a maximum of 40)","entries":[{"kind":"Skill Group","group":null,"label":"Trade Skills","prereq":false},{"kind":"Skill","group":null,"label":"Fitness","prereq":false},{"kind":"Skill","group":null,"label":"Martial Arts [Choose One]","prereq":false},{"kind":"Skill","group":null,"label":"Performance","prereq":false},{"kind":"Tech. Grp.","group":"kata","label":"Rank 1–2 Kata","prereq":true},{"kind":"Technique","group":"kata","label":"Open-Hand Style","prereq":true},{"kind":"Technique","group":"shuji","label":"Shallow Waters","prereq":true}]}},"tiers":[{"xp":0,"label":null,"rank":1,"school":"Doji Bureaucrat School","foundry_id":null,"rings":{"air":3,"earth":2,"fire":1,"water":3,"void":1},"skills":{"artisan":{"aesthetics":0,"composition":2,"design":1,"smithing":0},"martial":{"fitness":0,"melee":0,"ranged":0,"unarmed":2,"meditation":0,"tactics":0},"scholar":{"culture":2,"government":2,"medicine":0,"sentiment":1,"theology":0},"social":{"command":2,"courtesy":2,"games":0,"performance":0},"trade":{"commerce":0,"labor":0,"seafaring":0,"skulduggery":0,"survival":0}},"social":{"honor":69,"glory":71,"status":60,"ninjo":"Strictures too often interfere with a beautiful tale.\n\nShe escapes into literature, particularly pillow-books, and riding her horse, Kogorashi, a Utaku steed and wedding gift from her husband's family.","giri":"Currently, Kitsuki Kāgi, in service as an Emerald Magistrate under the Emperor.\n\nPreviously, she served Asahina Shigehiro, lord of the city of Shirogome, on issues of imperial law and legal arbitration.\n\nHer giri: Rule must bind, and if needed, contort.","bushido_tenets":{"paramount":"Courtesy","less_significant":"Courage"}},"derived":{"endurance":10,"composure":12,"focus":5,"vigilance":3,"void_points":2},"money":{"zeni":0,"koku":0,"bu":0},"advancements":[],"techniques":[{"name":"Courtier’s Resolve","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"shuji","rank":1,"description":"<ul><li>Warriors do battle with their bodies, and courtiers do battle with their minds. To maintain one’s composure while surrounded by the challenges of court, one must be able to clear and organize one’s mind, returning focus to the most vital tasks.</li><li>Once per scene as a Support action, you may spend 1 Void point to recover from strife.</li><li>Remove strife equal to your glory rank.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":222},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.KaIqecu4b1TpXZid"},{"name":"Stonewall Tactics","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"shuji","rank":1,"description":"<ul><li>The courtier makes themself impossible for the target to ignore, raising a pressing concern that must be addressed first or even physically planting themself between a rival and their allies.</li><li>When making a Social skill (Earth) or Martial skill (Earth) check targeting a character, you may spend (op) in the following way:</li><li>Earth (op)+: Increase the TN of any check the target makes that does not target you by 1 per (op) spent this way. This effect persists until the beginning of your next turn.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":216},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.edR9lIhccQ9wddX8"},{"name":"Procedure and Protocol","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"kind":"school_ability","rank":1,"description":"<p>When you cause a character to receive strife as a result of a check using a social approach, that character suffers additional strife equal to your school rank.</p>","text_source":"dsl","source":{"book":"court_of_stones","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.school-abilities-l5r-sortilege.Item.l3MWXTYlzmL4j247"}],"peculiarities":[{"name":"Scorn of [One Group]","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"water","types":"Interpersonal","description":"<ul><li>You have earned the ire of a particular group, which has seriously damaged your ability to work with its members or enlist their help. You have been barred from entering their facilities, and they refuse to meet or communicate with you directly. Confer with the GM to select a campaign-appropriate group when choosing this disadvantage.</li><li>When performing a check to interact with the chosen group that relies on your rapport with its members (such as a Courtesy [Water] check to persuade them to do something or a Performance [Water] check to impress a group of them), you must choose and reroll two dice containing success or explosive success. After resolving the check, if you failed, you gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":127},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.phzQyXvNxw7HVrgQ"},{"name":"Wordplay","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"passion","ring":"air","types":"Interpersonal, Mental","description":"<ul><li>You can always identify rhetorical and literary patterns in the works of others when reading or listening to them.</li><li>After performing a check to interpret or create a play on words (such as a Composition [Air] check to write a poem with a perfectly executed poetic pun or a Performance [Air] check to subtly imply something to your audience via a double meaning), you remove 3 strife.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":116},"uuid":"Compendium.l5r5e-compendia-sortilege.passions-l5r-sortilege.Item.QPLHN6JrL4Jshp4P"},{"name":"Fear of Death","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"anxiety","ring":"earth","types":"Mental, Physical","description":"<ul><li>You cannot voluntarily choose to die or sacrifice your life (including committing seppuku when honor demands it), and if there is a chance you could live, you must always pursue it.</li><li>After performing a check to risk your life or accept your mortality (such as a Meditation [Earth] check to find inner tranquility before battle or a Tactics [Earth] check to hold a position against long odds), you receive 3 strife. If this is the first time this has occurred this scene, gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":132},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.mjsfXGRv9ip0vn9n"},{"name":"Haunting","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"void","types":"Interpersonal, Spiritual","description":"<ul><li>The spirit has their own agenda (determined by the GM), which interferes with yours at inopportune times.</li><li>When you make a check to defy the will of the spirit haunting you (such as a Meditation [Void] check to find solace in meditation or a Skulduggery [Void] check to perform disreputable acts to survive), you must choose and reroll two dice containing success or explosive success. After resolving the check, if you failed, you gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":122},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.kc6gGspWMQATYqIO"},{"name":"Blessed Lineage","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"void","types":"Interpersonal, Spiritual","description":"<ul><li>Characters with status of 50 or higher understand that they might suffer a loss of prestige if they harm you, and thus do not choose to kill you as their first option, even if you are a political obstacle they would otherwise eliminate without hesitation.</li><li>When performing a check for which your esteemed lineage is a benefit (such as a Command [Void] check to challenge someone&#x27;s perception of a situation or a Government [Void] check to know the likelihood of a political eventuality), you may reroll up to two dice.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":103},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.tRfoACKusbLsicmy"},{"name":"Paragon of Courtesy","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"air","types":"Mental, Virtue","description":"<ul><li>Pick One: Compassion (Water), Courage (Fire), Courtesy (Air), Duty and Loyalty (Earth), Honor (Void), Righteousness (Void), Sincerity (Void). A character may have multiple instances of this advantage for different tenets. Each tenet counts as a separate advantage. You believe utterly in the chosen Bushidō tenet, and others instinctively discern that your actions are genuine when you act in accordance with it.</li><li>When performing a check for which you need to convince others of, or leverage your faith in, the Bushidō tenet (such as a Performance check to recount a tale that impresses its importance upon others or a Martial Arts [Melee] check to take up arms for this cause), you may reroll up to two dice.</li></ul>","text_source":"dsl","text_via":"Paragon of a Bushidō Tenet","source":{"book":"core_rulebook","page":108},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.fCqRyrkg6meX21xR"},{"name":"Dark Secret","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":2,"kind":"anxiety","ring":"void","types":"Interpersonal","description":"<ul><li>You have a dark secret that, if exposed, could bring ruin upon your house and disgrace your ancestors and descendants alike. If the details of this secret become public, your glory value decreases dramatically, as if you had lost staked glory (by 10 to 20). Depending on the secret, your status value might also decrease considerably (by 5 to 10), as if you had lost staked status.</li><li>After performing a check to assert your will over yourself or others (such as a Command [Void] check to order troops to fight to the bitter end or a Meditation [Void] check to find inner peace), you receive 3 strife. If this is the first time this has occurred this scene, gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":132},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.bd12LEtxVlmVVckt"},{"name":"Famously Successful","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":2,"kind":"distinction","ring":"fire","types":"Fame, Interpersonal","description":"<ul><li>Other people have heard of you for your ability to get results at any cost, and they believe it by default unless given evidence to the contrary.</li><li>When performing a check for which you need to leverage your reputation for efficiency (such as a Courtesy [Fire] check to convince your lord to give you a position or a Tactics [Fire] check to get enemy troops to withdraw in the face of a show of force), you may reroll up to two dice.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":105},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.ITdK6Jhu73A3rXPx"},{"name":"Legal Scholarship","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":3,"kind":"distinction","ring":"air","types":"Interpersonal, Social","description":"<ul><li>Your family possesses old legal documents from Rokugani, Qamarist, and other legal traditions.</li><li>When performing a check to interact with a legal body or using a legal code, you may reroll up to two dice.</li></ul>","text_source":"dsl","source":{"book":"children_of_the_five_winds","page":93},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.BB7QfDAYqyo65Kap"},{"name":"Paragon of Courage","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":3,"kind":"distinction","ring":"fire","types":"Mental, Virtue","description":"<ul><li>Pick One: Compassion (Water), Courage (Fire), Courtesy (Air), Duty and Loyalty (Earth), Honor (Void), Righteousness (Void), Sincerity (Void). A character may have multiple instances of this advantage for different tenets. Each tenet counts as a separate advantage. You believe utterly in the chosen Bushidō tenet, and others instinctively discern that your actions are genuine when you act in accordance with it.</li><li>When performing a check for which you need to convince others of, or leverage your faith in, the Bushidō tenet (such as a Performance check to recount a tale that impresses its importance upon others or a Martial Arts [Melee] check to take up arms for this cause), you may reroll up to two dice.</li></ul>","text_source":"dsl","text_via":"Paragon of a Bushidō Tenet","source":{"book":"core_rulebook","page":108},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.trppadBbshGjbSP2"}],"titles":[],"bonds":[{"name":"Shinjo Harunobu","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"custom":true,"description":"<p><span class=\"fontstyle0\">Samurai are expected to place romantic love below their obligations to family and clan—but the human heart is not so easily confined. Many samurai who fall in love keep their relationship secret, while others are more overt. The following are suggested narrative effects for a character with a Lover bond:</span></p><ul><li><p><span class=\"fontstyle0\">- A lover seeks to spend time with you, writes letters to you, and is willing to assist you in ways that do not require publicly acknowledging your bond (giving you information key to pursuing a desired goal, encouraging you to pursue your personal interests, helping you to deal with emotions you usually must keep to yourself), and they expect you to do the same.</span></p></li><li><p><span class=\"fontstyle0\">Generally, your lover’s allies do not acknowledge your relationship. Some might be favorably disposed to you covertly if you make their ally happy (and unfavorably disposed if you make them unhappy), while others might be jealous of the attention you receive. Your lover’s enemies might target you to attempt to gain leverage over your lover.</span></p></li><li><p><span class=\"fontstyle0\">If your bond rank is 3 or higher, a lover is more overt about your relationship, allowing them to assist you more publicly (such as giving you letters of introduction to officials above your status, allowing you to use their name to pursue your goals, and even helping you directly), and they expect the same from you.</span></p></li></ul><p></p><p><span class=\"fontstyle3\"><strong>Bond Ability:</strong> With You, the Storm Subsides</span></p>","source_reference":{"source":"","page":0}}],"signature_scrolls":[],"gear":[{"name":"Wakizashi","quantity":1,"description":"<p>Whereas the katana represents a samurai’s status as a warrior, the wakizashi represents their place in Rokugan’s social order and strict caste system. The wakizashi is a small, katana-like sword usually two to three feet in length, with the same flexible blade and lethal edge. It is often made as part of a pair, with the same decorations as its matched katana. The wakizashi also fills another role: it clearly signals that its wearer is a samurai, and a person of honor who will make the ultimate sacrifice for their ideals and their master. It is the tool with which a samurai commits seppuku: ritual suicide, the last protest of an aggrieved and honorable samurai.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":233},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.S1MG4qPHEV3N8XnO","damage":3,"deadliness":5,"range":"0-1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"15 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Ceremonial Clothes","quantity":1,"description":"<p>Ceremonial clothing is any garment worn during an official ceremony, from a samurai’s court kimono to the accoutrement of the Imperial family. Ceremonial clothing is often richly decorated and offers little protection.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.K61XHG9GnFLieqjc","armor":{"physical":1,"supernatural":0},"rarity":"4","zeni":"1 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000010","name":"Resplendent"}]},{"name":"Calligraphy Set","quantity":1,"description":"<p>These ornate boxes contain items a practiced callig- rapher needs to craft books, letters, scrolls, and other written communications. It consists of a small wooden box that contains a variety of brushes, inkstones, and pigments; a small bowl for water; and a small bag of sand for drying. Calligraphers and scribes customari- ly carry a calligraphy set, as so do some samurai and courtiers who prefer to write their own correspon- dence.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":242},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.MWzx5Wiu6xcCWc9J","rarity":"3","zeni":"1 bu"},{"name":"Personal Seal or Chop","quantity":1,"description":"<p>A personal chop is used by samurai to verify their iden- tity and sign documents, among other official business. Each one is a unique design that is registered with the Miya family. Using another samurai’s chop is consid- ered both an insult and a serious crime.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":243},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.UU5eQKPBQZ9ilOTF","rarity":"6","zeni":"4 bu","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"}]},{"name":"Blank Forms","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]},{"name":"Legal Primer","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]},{"name":"Hano no Ami Pillow Book","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]},{"name":"Scroll of Authority from Magistrate of Shirogome","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]}]},{"xp":20,"label":"Rank 2","rank":2,"school":"Doji Bureaucrat School","foundry_id":null,"rings":{"air":3,"earth":2,"fire":1,"water":3,"void":1},"skills":{"artisan":{"aesthetics":0,"composition":2,"design":1,"smithing":0},"martial":{"fitness":0,"melee":0,"ranged":0,"unarmed":2,"meditation":0,"tactics":0},"scholar":{"culture":2,"government":3,"medicine":0,"sentiment":2,"theology":0},"social":{"command":2,"courtesy":2,"games":0,"performance":0},"trade":{"commerce":0,"labor":0,"seafaring":0,"skulduggery":0,"survival":0}},"social":{"honor":69,"glory":71,"status":60,"ninjo":"Strictures too often interfere with a beautiful tale.\n\nShe escapes into literature, particularly pillow-books, and riding her horse, Kogorashi, a Utaku steed and wedding gift from her husband's family.","giri":"Currently, Kitsuki Kāgi, in service as an Emerald Magistrate under the Emperor.\n\nPreviously, she served Asahina Shigehiro, lord of the city of Shirogome, on issues of imperial law and legal arbitration.\n\nHer giri: Rule must bind, and if needed, contort.","bushido_tenets":{"paramount":"Courtesy","less_significant":"Courage"}},"derived":{"endurance":10,"composure":12,"focus":5,"vigilance":3,"void_points":2},"money":{"zeni":0,"koku":0,"bu":0},"advancements":[{"label":"Government +1 (1 -> 2)","type":"skill","skill":"government","ring":"void","at_rank":1,"xp":4,"in_curriculum":true},{"label":"Government +1 (2 -> 3)","type":"skill","skill":"government","ring":"void","at_rank":1,"xp":6,"in_curriculum":true},{"label":"Sentiment +1 (1 -> 2)","type":"skill","skill":"sentiment","ring":"void","at_rank":1,"xp":4,"in_curriculum":true}],"techniques":[{"name":"Courtier’s Resolve","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"shuji","rank":1,"description":"<ul><li>Warriors do battle with their bodies, and courtiers do battle with their minds. To maintain one’s composure while surrounded by the challenges of court, one must be able to clear and organize one’s mind, returning focus to the most vital tasks.</li><li>Once per scene as a Support action, you may spend 1 Void point to recover from strife.</li><li>Remove strife equal to your glory rank.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":222},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.KaIqecu4b1TpXZid"},{"name":"Stonewall Tactics","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"shuji","rank":1,"description":"<ul><li>The courtier makes themself impossible for the target to ignore, raising a pressing concern that must be addressed first or even physically planting themself between a rival and their allies.</li><li>When making a Social skill (Earth) or Martial skill (Earth) check targeting a character, you may spend (op) in the following way:</li><li>Earth (op)+: Increase the TN of any check the target makes that does not target you by 1 per (op) spent this way. This effect persists until the beginning of your next turn.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":216},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.edR9lIhccQ9wddX8"},{"name":"Procedure and Protocol","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"kind":"school_ability","rank":1,"description":"<p>When you cause a character to receive strife as a result of a check using a social approach, that character suffers additional strife equal to your school rank.</p>","text_source":"dsl","source":{"book":"court_of_stones","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.school-abilities-l5r-sortilege.Item.l3MWXTYlzmL4j247"},{"name":"Beware The Smallest Mouse","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"shuji","rank":1,"description":"<ul><li>Type: Shūji</li><li>Subtype: Water Shūji</li><li>Rank: 1</li><li>Activation: When you make a Social skill (Water) check targeting one or more characters</li><li>Opportunities: Water (op)(op)+: While interacting with you, the target treats their vigilance as 1 lower per (op)(op) spent and decreases TN of social checks targeting you by 1. Persists until end of scene.</li></ul>","text_source":"dsl","source":{"book":"court_of_stones","page":118},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.6RjitPKJypourgTx"},{"name":"Treaty Signing","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"ritual","rank":2,"description":"<ul><li>Type: Ritual</li><li>Rank: 2</li><li>Activation: Once per game session as a downtime activity</li><li>Check: TN 2 Composition (Fire) to write agreement, then TN 3 Government (Air) targeting participants</li><li>If you succeed, agreement has no loopholes. Each participant stakes 10 honor on upholding the agreement. Anyone who later breaks it loses staked honor unless another participant broke it first.</li><li>Opportunities: (op)+: All participants stake 1 additional honor plus 1 per (op) spent. (op)(op)(op): If you succeed, you need only stake half the honor other participants stake.</li></ul>","text_source":"dsl","source":{"book":"court_of_stones","page":116},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-rituals-l5r-sortilege.Item.8crnCQbpwgQyk2Ry","skill":"composition"}],"peculiarities":[{"name":"Scorn of [One Group]","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"water","types":"Interpersonal","description":"<ul><li>You have earned the ire of a particular group, which has seriously damaged your ability to work with its members or enlist their help. You have been barred from entering their facilities, and they refuse to meet or communicate with you directly. Confer with the GM to select a campaign-appropriate group when choosing this disadvantage.</li><li>When performing a check to interact with the chosen group that relies on your rapport with its members (such as a Courtesy [Water] check to persuade them to do something or a Performance [Water] check to impress a group of them), you must choose and reroll two dice containing success or explosive success. After resolving the check, if you failed, you gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":127},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.phzQyXvNxw7HVrgQ"},{"name":"Wordplay","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"passion","ring":"air","types":"Interpersonal, Mental","description":"<ul><li>You can always identify rhetorical and literary patterns in the works of others when reading or listening to them.</li><li>After performing a check to interpret or create a play on words (such as a Composition [Air] check to write a poem with a perfectly executed poetic pun or a Performance [Air] check to subtly imply something to your audience via a double meaning), you remove 3 strife.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":116},"uuid":"Compendium.l5r5e-compendia-sortilege.passions-l5r-sortilege.Item.QPLHN6JrL4Jshp4P"},{"name":"Fear of Death","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"anxiety","ring":"earth","types":"Mental, Physical","description":"<ul><li>You cannot voluntarily choose to die or sacrifice your life (including committing seppuku when honor demands it), and if there is a chance you could live, you must always pursue it.</li><li>After performing a check to risk your life or accept your mortality (such as a Meditation [Earth] check to find inner tranquility before battle or a Tactics [Earth] check to hold a position against long odds), you receive 3 strife. If this is the first time this has occurred this scene, gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":132},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.mjsfXGRv9ip0vn9n"},{"name":"Haunting","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"void","types":"Interpersonal, Spiritual","description":"<ul><li>The spirit has their own agenda (determined by the GM), which interferes with yours at inopportune times.</li><li>When you make a check to defy the will of the spirit haunting you (such as a Meditation [Void] check to find solace in meditation or a Skulduggery [Void] check to perform disreputable acts to survive), you must choose and reroll two dice containing success or explosive success. After resolving the check, if you failed, you gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":122},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.kc6gGspWMQATYqIO"},{"name":"Blessed Lineage","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"void","types":"Interpersonal, Spiritual","description":"<ul><li>Characters with status of 50 or higher understand that they might suffer a loss of prestige if they harm you, and thus do not choose to kill you as their first option, even if you are a political obstacle they would otherwise eliminate without hesitation.</li><li>When performing a check for which your esteemed lineage is a benefit (such as a Command [Void] check to challenge someone&#x27;s perception of a situation or a Government [Void] check to know the likelihood of a political eventuality), you may reroll up to two dice.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":103},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.tRfoACKusbLsicmy"},{"name":"Paragon of Courtesy","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"air","types":"Mental, Virtue","description":"<ul><li>Pick One: Compassion (Water), Courage (Fire), Courtesy (Air), Duty and Loyalty (Earth), Honor (Void), Righteousness (Void), Sincerity (Void). A character may have multiple instances of this advantage for different tenets. Each tenet counts as a separate advantage. You believe utterly in the chosen Bushidō tenet, and others instinctively discern that your actions are genuine when you act in accordance with it.</li><li>When performing a check for which you need to convince others of, or leverage your faith in, the Bushidō tenet (such as a Performance check to recount a tale that impresses its importance upon others or a Martial Arts [Melee] check to take up arms for this cause), you may reroll up to two dice.</li></ul>","text_source":"dsl","text_via":"Paragon of a Bushidō Tenet","source":{"book":"core_rulebook","page":108},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.fCqRyrkg6meX21xR"},{"name":"Dark Secret","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":2,"kind":"anxiety","ring":"void","types":"Interpersonal","description":"<ul><li>You have a dark secret that, if exposed, could bring ruin upon your house and disgrace your ancestors and descendants alike. If the details of this secret become public, your glory value decreases dramatically, as if you had lost staked glory (by 10 to 20). Depending on the secret, your status value might also decrease considerably (by 5 to 10), as if you had lost staked status.</li><li>After performing a check to assert your will over yourself or others (such as a Command [Void] check to order troops to fight to the bitter end or a Meditation [Void] check to find inner peace), you receive 3 strife. If this is the first time this has occurred this scene, gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":132},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.bd12LEtxVlmVVckt"},{"name":"Famously Successful","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":2,"kind":"distinction","ring":"fire","types":"Fame, Interpersonal","description":"<ul><li>Other people have heard of you for your ability to get results at any cost, and they believe it by default unless given evidence to the contrary.</li><li>When performing a check for which you need to leverage your reputation for efficiency (such as a Courtesy [Fire] check to convince your lord to give you a position or a Tactics [Fire] check to get enemy troops to withdraw in the face of a show of force), you may reroll up to two dice.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":105},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.ITdK6Jhu73A3rXPx"},{"name":"Legal Scholarship","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":3,"kind":"distinction","ring":"air","types":"Interpersonal, Social","description":"<ul><li>Your family possesses old legal documents from Rokugani, Qamarist, and other legal traditions.</li><li>When performing a check to interact with a legal body or using a legal code, you may reroll up to two dice.</li></ul>","text_source":"dsl","source":{"book":"children_of_the_five_winds","page":93},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.BB7QfDAYqyo65Kap"},{"name":"Paragon of Courage","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":3,"kind":"distinction","ring":"fire","types":"Mental, Virtue","description":"<ul><li>Pick One: Compassion (Water), Courage (Fire), Courtesy (Air), Duty and Loyalty (Earth), Honor (Void), Righteousness (Void), Sincerity (Void). A character may have multiple instances of this advantage for different tenets. Each tenet counts as a separate advantage. You believe utterly in the chosen Bushidō tenet, and others instinctively discern that your actions are genuine when you act in accordance with it.</li><li>When performing a check for which you need to convince others of, or leverage your faith in, the Bushidō tenet (such as a Performance check to recount a tale that impresses its importance upon others or a Martial Arts [Melee] check to take up arms for this cause), you may reroll up to two dice.</li></ul>","text_source":"dsl","text_via":"Paragon of a Bushidō Tenet","source":{"book":"core_rulebook","page":108},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.trppadBbshGjbSP2"}],"titles":[],"bonds":[{"name":"Shinjo Harunobu","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"custom":true,"description":"<p><span class=\"fontstyle0\">Samurai are expected to place romantic love below their obligations to family and clan—but the human heart is not so easily confined. Many samurai who fall in love keep their relationship secret, while others are more overt. The following are suggested narrative effects for a character with a Lover bond:</span></p><ul><li><p><span class=\"fontstyle0\">- A lover seeks to spend time with you, writes letters to you, and is willing to assist you in ways that do not require publicly acknowledging your bond (giving you information key to pursuing a desired goal, encouraging you to pursue your personal interests, helping you to deal with emotions you usually must keep to yourself), and they expect you to do the same.</span></p></li><li><p><span class=\"fontstyle0\">Generally, your lover’s allies do not acknowledge your relationship. Some might be favorably disposed to you covertly if you make their ally happy (and unfavorably disposed if you make them unhappy), while others might be jealous of the attention you receive. Your lover’s enemies might target you to attempt to gain leverage over your lover.</span></p></li><li><p><span class=\"fontstyle0\">If your bond rank is 3 or higher, a lover is more overt about your relationship, allowing them to assist you more publicly (such as giving you letters of introduction to officials above your status, allowing you to use their name to pursue your goals, and even helping you directly), and they expect the same from you.</span></p></li></ul><p></p><p><span class=\"fontstyle3\"><strong>Bond Ability:</strong> With You, the Storm Subsides</span></p>","source_reference":{"source":"","page":0}}],"signature_scrolls":[],"gear":[{"name":"Wakizashi","quantity":1,"description":"<p>Whereas the katana represents a samurai’s status as a warrior, the wakizashi represents their place in Rokugan’s social order and strict caste system. The wakizashi is a small, katana-like sword usually two to three feet in length, with the same flexible blade and lethal edge. It is often made as part of a pair, with the same decorations as its matched katana. The wakizashi also fills another role: it clearly signals that its wearer is a samurai, and a person of honor who will make the ultimate sacrifice for their ideals and their master. It is the tool with which a samurai commits seppuku: ritual suicide, the last protest of an aggrieved and honorable samurai.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":233},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.S1MG4qPHEV3N8XnO","damage":3,"deadliness":5,"range":"0-1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"15 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Ceremonial Clothes","quantity":1,"description":"<p>Ceremonial clothing is any garment worn during an official ceremony, from a samurai’s court kimono to the accoutrement of the Imperial family. Ceremonial clothing is often richly decorated and offers little protection.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.K61XHG9GnFLieqjc","armor":{"physical":1,"supernatural":0},"rarity":"4","zeni":"1 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000010","name":"Resplendent"}]},{"name":"Calligraphy Set","quantity":1,"description":"<p>These ornate boxes contain items a practiced callig- rapher needs to craft books, letters, scrolls, and other written communications. It consists of a small wooden box that contains a variety of brushes, inkstones, and pigments; a small bowl for water; and a small bag of sand for drying. Calligraphers and scribes customari- ly carry a calligraphy set, as so do some samurai and courtiers who prefer to write their own correspon- dence.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":242},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.MWzx5Wiu6xcCWc9J","rarity":"3","zeni":"1 bu"},{"name":"Personal Seal or Chop","quantity":1,"description":"<p>A personal chop is used by samurai to verify their iden- tity and sign documents, among other official business. Each one is a unique design that is registered with the Miya family. Using another samurai’s chop is consid- ered both an insult and a serious crime.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":243},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.UU5eQKPBQZ9ilOTF","rarity":"6","zeni":"4 bu","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"}]},{"name":"Blank Forms","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]},{"name":"Legal Primer","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]},{"name":"Hano no Ami Pillow Book","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]},{"name":"Scroll of Authority from Magistrate of Shirogome","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]}]},{"xp":50,"label":"Rank 3","rank":3,"school":"Doji Bureaucrat School","foundry_id":null,"rings":{"air":3,"earth":2,"fire":2,"water":3,"void":2},"skills":{"artisan":{"aesthetics":0,"composition":2,"design":1,"smithing":0},"martial":{"fitness":0,"melee":0,"ranged":0,"unarmed":2,"meditation":0,"tactics":0},"scholar":{"culture":2,"government":3,"medicine":0,"sentiment":2,"theology":0},"social":{"command":2,"courtesy":3,"games":0,"performance":0},"trade":{"commerce":0,"labor":0,"seafaring":0,"skulduggery":0,"survival":0}},"social":{"honor":69,"glory":71,"status":60,"ninjo":"Strictures too often interfere with a beautiful tale.\n\nShe escapes into literature, particularly pillow-books, and riding her horse, Kogorashi, a Utaku steed and wedding gift from her husband's family.","giri":"Currently, Kitsuki Kāgi, in service as an Emerald Magistrate under the Emperor.\n\nPreviously, she served Asahina Shigehiro, lord of the city of Shirogome, on issues of imperial law and legal arbitration.\n\nHer giri: Rule must bind, and if needed, contort.","bushido_tenets":{"paramount":"Courtesy","less_significant":"Courage"}},"derived":{"endurance":10,"composure":12,"focus":5,"vigilance":3,"void_points":2},"money":{"zeni":0,"koku":0,"bu":0},"advancements":[{"label":"Government +1 (1 -> 2)","type":"skill","skill":"government","ring":"void","at_rank":1,"xp":4,"in_curriculum":true},{"label":"Government +1 (2 -> 3)","type":"skill","skill":"government","ring":"void","at_rank":1,"xp":6,"in_curriculum":true},{"label":"Sentiment +1 (1 -> 2)","type":"skill","skill":"sentiment","ring":"void","at_rank":1,"xp":4,"in_curriculum":true},{"label":"Fire +1 (1 -> 2)","type":"ring","ring":"fire","at_rank":2,"xp":6,"in_curriculum":false},{"label":"Void +1 (1 -> 2)","type":"ring","ring":"void","at_rank":2,"xp":6,"in_curriculum":false},{"label":"Courtesy +1 (2 -> 3)","type":"skill","skill":"courtesy","ring":"void","at_rank":2,"xp":6,"in_curriculum":true}],"techniques":[{"name":"Courtier’s Resolve","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"shuji","rank":1,"description":"<ul><li>Warriors do battle with their bodies, and courtiers do battle with their minds. To maintain one’s composure while surrounded by the challenges of court, one must be able to clear and organize one’s mind, returning focus to the most vital tasks.</li><li>Once per scene as a Support action, you may spend 1 Void point to recover from strife.</li><li>Remove strife equal to your glory rank.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":222},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.KaIqecu4b1TpXZid"},{"name":"Stonewall Tactics","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"shuji","rank":1,"description":"<ul><li>The courtier makes themself impossible for the target to ignore, raising a pressing concern that must be addressed first or even physically planting themself between a rival and their allies.</li><li>When making a Social skill (Earth) or Martial skill (Earth) check targeting a character, you may spend (op) in the following way:</li><li>Earth (op)+: Increase the TN of any check the target makes that does not target you by 1 per (op) spent this way. This effect persists until the beginning of your next turn.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":216},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.edR9lIhccQ9wddX8"},{"name":"Procedure and Protocol","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"kind":"school_ability","rank":1,"description":"<p>When you cause a character to receive strife as a result of a check using a social approach, that character suffers additional strife equal to your school rank.</p>","text_source":"dsl","source":{"book":"court_of_stones","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.school-abilities-l5r-sortilege.Item.l3MWXTYlzmL4j247"},{"name":"Beware The Smallest Mouse","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"shuji","rank":1,"description":"<ul><li>Type: Shūji</li><li>Subtype: Water Shūji</li><li>Rank: 1</li><li>Activation: When you make a Social skill (Water) check targeting one or more characters</li><li>Opportunities: Water (op)(op)+: While interacting with you, the target treats their vigilance as 1 lower per (op)(op) spent and decreases TN of social checks targeting you by 1. Persists until end of scene.</li></ul>","text_source":"dsl","source":{"book":"court_of_stones","page":118},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.6RjitPKJypourgTx"},{"name":"Treaty Signing","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"ritual","rank":2,"description":"<ul><li>Type: Ritual</li><li>Rank: 2</li><li>Activation: Once per game session as a downtime activity</li><li>Check: TN 2 Composition (Fire) to write agreement, then TN 3 Government (Air) targeting participants</li><li>If you succeed, agreement has no loopholes. Each participant stakes 10 honor on upholding the agreement. Anyone who later breaks it loses staked honor unless another participant broke it first.</li><li>Opportunities: (op)+: All participants stake 1 additional honor plus 1 per (op) spent. (op)(op)(op): If you succeed, you need only stake half the honor other participants stake.</li></ul>","text_source":"dsl","source":{"book":"court_of_stones","page":116},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-rituals-l5r-sortilege.Item.8crnCQbpwgQyk2Ry","skill":"composition"},{"name":"Civility Foremost","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"shuji","rank":2,"description":"<ul><li>Samurai are warriors, but there are many contexts in which violence is inappropriate. Many strictures exist around the times weapons can and cannot be drawn. A courtier who has memorized the rules of such engagements can articulate why fighting would be improper or profane in nearly any situation.</li><li>As a Scheme action, make a Command or Courtesy (Earth) check targeting one character to claim protection for an individual of your choice by rights of honor. The TN of the check is equal to the target&#x27;s vigilance.</li><li>If you succeed, the target must forfeit honor equal to your Earth Ring plus your bonus successes and suffer that much strife to perform an Attack or Scheme action targeting the chosen individual. This effect persists until the end of the scene, or until the target performs an Attack or Scheme action.</li><li>Earth (op)+: Choose one additional target with vigilance lower than or equal to your first target&#x27;s vigilance per (op) spent this way.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":216},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.qCWzsCP48rEbiZ59","skill":"command,courtesy"},{"name":"Well of Desire","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"shuji","rank":1,"description":"<ul><li>Bribery is considered to be corruption in Rokugan, yet gift exchanges and gift giving is a time-honored tradition. The shrewdest courtiers can engineer scenarios in which their targets cannot refuse their gifts without tarnishing their reputations. Thus, the recipient of such a poisoned gift might find it preferable to owe the courtier a favor than to be shamed in public.</li><li>When you make a Courtesy (Water) check to present a gift to a target, you may spend (op) as follows:</li><li>Water (op): To refuse your gift, your target must forfeit glory equal to your Water Ring. Additionally, if the gift is something that the target desires, the target also must suffer strife equal to its rarity to refuse it. If your target accepts the gift, reduce the TN of your next Social skill check targeting them by the rarity of the item (to a minimum of 1).</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":221},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.DE7tPCTvvSVptjRj"},{"name":"The Wind Blows Both Ways","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"shuji","rank":3,"description":"<ul><li>A word in the right ear at the right time can enhance the accomplishment of another, or a cutting slight can diminish their success in the eyes of those who matter.</li><li>When you make a Courtesy or Performance (Air) check targeting another character, you may spend (op) in the following ways:</li><li>Air (op)+: The next time the target receives a glory award, increase the glory they gain by 1 per (op) spent this way. This effect persists until the end of the scene.</li><li>Air (op)+: The next time the target forfeits or stakes glory, increase the glory they must forfeit or stake by 1 per (op) spent this way. This effect persists until the end of the scene.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":215},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.gA96njIZ1sRcveWQ"},{"name":"Call to Ride","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"shuji","rank":1,"description":"<ul><li>Activation: As a Support action, you can make a TN 1 Survival (Water) check targeting your mount or animal companion, provided it is within range 5 of you.</li><li>If you succeed, your mount or animal companion immediately moves up to 2 range bands toward you, plus 1 additional per two bonus successes. If it is a mount and ends at range 0, you can immediately mount it.</li><li>Opportunities: (op)(op): Increase TN of Attack action checks targeting you and your mount/companion by 1 until end of your next turn. (op)(op): If you perform a Maneuver action after mounting, you may move up to 2 range bands instead of 1.</li></ul>","text_source":"dsl","source":{"book":"children_of_the_five_winds","page":115},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.hk3fDtNibUKG9BOJ","skill":"survival"}],"peculiarities":[{"name":"Scorn of [One Group]","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"water","types":"Interpersonal","description":"<ul><li>You have earned the ire of a particular group, which has seriously damaged your ability to work with its members or enlist their help. You have been barred from entering their facilities, and they refuse to meet or communicate with you directly. Confer with the GM to select a campaign-appropriate group when choosing this disadvantage.</li><li>When performing a check to interact with the chosen group that relies on your rapport with its members (such as a Courtesy [Water] check to persuade them to do something or a Performance [Water] check to impress a group of them), you must choose and reroll two dice containing success or explosive success. After resolving the check, if you failed, you gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":127},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.phzQyXvNxw7HVrgQ"},{"name":"Wordplay","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"passion","ring":"air","types":"Interpersonal, Mental","description":"<ul><li>You can always identify rhetorical and literary patterns in the works of others when reading or listening to them.</li><li>After performing a check to interpret or create a play on words (such as a Composition [Air] check to write a poem with a perfectly executed poetic pun or a Performance [Air] check to subtly imply something to your audience via a double meaning), you remove 3 strife.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":116},"uuid":"Compendium.l5r5e-compendia-sortilege.passions-l5r-sortilege.Item.QPLHN6JrL4Jshp4P"},{"name":"Fear of Death","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"anxiety","ring":"earth","types":"Mental, Physical","description":"<ul><li>You cannot voluntarily choose to die or sacrifice your life (including committing seppuku when honor demands it), and if there is a chance you could live, you must always pursue it.</li><li>After performing a check to risk your life or accept your mortality (such as a Meditation [Earth] check to find inner tranquility before battle or a Tactics [Earth] check to hold a position against long odds), you receive 3 strife. If this is the first time this has occurred this scene, gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":132},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.mjsfXGRv9ip0vn9n"},{"name":"Haunting","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"void","types":"Interpersonal, Spiritual","description":"<ul><li>The spirit has their own agenda (determined by the GM), which interferes with yours at inopportune times.</li><li>When you make a check to defy the will of the spirit haunting you (such as a Meditation [Void] check to find solace in meditation or a Skulduggery [Void] check to perform disreputable acts to survive), you must choose and reroll two dice containing success or explosive success. After resolving the check, if you failed, you gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":122},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.kc6gGspWMQATYqIO"},{"name":"Blessed Lineage","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"void","types":"Interpersonal, Spiritual","description":"<ul><li>Characters with status of 50 or higher understand that they might suffer a loss of prestige if they harm you, and thus do not choose to kill you as their first option, even if you are a political obstacle they would otherwise eliminate without hesitation.</li><li>When performing a check for which your esteemed lineage is a benefit (such as a Command [Void] check to challenge someone&#x27;s perception of a situation or a Government [Void] check to know the likelihood of a political eventuality), you may reroll up to two dice.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":103},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.tRfoACKusbLsicmy"},{"name":"Paragon of Courtesy","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"air","types":"Mental, Virtue","description":"<ul><li>Pick One: Compassion (Water), Courage (Fire), Courtesy (Air), Duty and Loyalty (Earth), Honor (Void), Righteousness (Void), Sincerity (Void). A character may have multiple instances of this advantage for different tenets. Each tenet counts as a separate advantage. You believe utterly in the chosen Bushidō tenet, and others instinctively discern that your actions are genuine when you act in accordance with it.</li><li>When performing a check for which you need to convince others of, or leverage your faith in, the Bushidō tenet (such as a Performance check to recount a tale that impresses its importance upon others or a Martial Arts [Melee] check to take up arms for this cause), you may reroll up to two dice.</li></ul>","text_source":"dsl","text_via":"Paragon of a Bushidō Tenet","source":{"book":"core_rulebook","page":108},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.fCqRyrkg6meX21xR"},{"name":"Dark Secret","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":2,"kind":"anxiety","ring":"void","types":"Interpersonal","description":"<ul><li>You have a dark secret that, if exposed, could bring ruin upon your house and disgrace your ancestors and descendants alike. If the details of this secret become public, your glory value decreases dramatically, as if you had lost staked glory (by 10 to 20). Depending on the secret, your status value might also decrease considerably (by 5 to 10), as if you had lost staked status.</li><li>After performing a check to assert your will over yourself or others (such as a Command [Void] check to order troops to fight to the bitter end or a Meditation [Void] check to find inner peace), you receive 3 strife. If this is the first time this has occurred this scene, gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":132},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.bd12LEtxVlmVVckt"},{"name":"Famously Successful","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":2,"kind":"distinction","ring":"fire","types":"Fame, Interpersonal","description":"<ul><li>Other people have heard of you for your ability to get results at any cost, and they believe it by default unless given evidence to the contrary.</li><li>When performing a check for which you need to leverage your reputation for efficiency (such as a Courtesy [Fire] check to convince your lord to give you a position or a Tactics [Fire] check to get enemy troops to withdraw in the face of a show of force), you may reroll up to two dice.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":105},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.ITdK6Jhu73A3rXPx"},{"name":"Legal Scholarship","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":3,"kind":"distinction","ring":"air","types":"Interpersonal, Social","description":"<ul><li>Your family possesses old legal documents from Rokugani, Qamarist, and other legal traditions.</li><li>When performing a check to interact with a legal body or using a legal code, you may reroll up to two dice.</li></ul>","text_source":"dsl","source":{"book":"children_of_the_five_winds","page":93},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.BB7QfDAYqyo65Kap"},{"name":"Paragon of Courage","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":3,"kind":"distinction","ring":"fire","types":"Mental, Virtue","description":"<ul><li>Pick One: Compassion (Water), Courage (Fire), Courtesy (Air), Duty and Loyalty (Earth), Honor (Void), Righteousness (Void), Sincerity (Void). A character may have multiple instances of this advantage for different tenets. Each tenet counts as a separate advantage. You believe utterly in the chosen Bushidō tenet, and others instinctively discern that your actions are genuine when you act in accordance with it.</li><li>When performing a check for which you need to convince others of, or leverage your faith in, the Bushidō tenet (such as a Performance check to recount a tale that impresses its importance upon others or a Martial Arts [Melee] check to take up arms for this cause), you may reroll up to two dice.</li></ul>","text_source":"dsl","text_via":"Paragon of a Bushidō Tenet","source":{"book":"core_rulebook","page":108},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.trppadBbshGjbSP2"}],"titles":[],"bonds":[{"name":"Shinjo Harunobu","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"custom":true,"description":"<p><span class=\"fontstyle0\">Samurai are expected to place romantic love below their obligations to family and clan—but the human heart is not so easily confined. Many samurai who fall in love keep their relationship secret, while others are more overt. The following are suggested narrative effects for a character with a Lover bond:</span></p><ul><li><p><span class=\"fontstyle0\">- A lover seeks to spend time with you, writes letters to you, and is willing to assist you in ways that do not require publicly acknowledging your bond (giving you information key to pursuing a desired goal, encouraging you to pursue your personal interests, helping you to deal with emotions you usually must keep to yourself), and they expect you to do the same.</span></p></li><li><p><span class=\"fontstyle0\">Generally, your lover’s allies do not acknowledge your relationship. Some might be favorably disposed to you covertly if you make their ally happy (and unfavorably disposed if you make them unhappy), while others might be jealous of the attention you receive. Your lover’s enemies might target you to attempt to gain leverage over your lover.</span></p></li><li><p><span class=\"fontstyle0\">If your bond rank is 3 or higher, a lover is more overt about your relationship, allowing them to assist you more publicly (such as giving you letters of introduction to officials above your status, allowing you to use their name to pursue your goals, and even helping you directly), and they expect the same from you.</span></p></li></ul><p></p><p><span class=\"fontstyle3\"><strong>Bond Ability:</strong> With You, the Storm Subsides</span></p>","source_reference":{"source":"","page":0}}],"signature_scrolls":[],"gear":[{"name":"Wakizashi","quantity":1,"description":"<p>Whereas the katana represents a samurai’s status as a warrior, the wakizashi represents their place in Rokugan’s social order and strict caste system. The wakizashi is a small, katana-like sword usually two to three feet in length, with the same flexible blade and lethal edge. It is often made as part of a pair, with the same decorations as its matched katana. The wakizashi also fills another role: it clearly signals that its wearer is a samurai, and a person of honor who will make the ultimate sacrifice for their ideals and their master. It is the tool with which a samurai commits seppuku: ritual suicide, the last protest of an aggrieved and honorable samurai.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":233},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.S1MG4qPHEV3N8XnO","damage":3,"deadliness":5,"range":"0-1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"15 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Ceremonial Clothes","quantity":1,"description":"<p>Ceremonial clothing is any garment worn during an official ceremony, from a samurai’s court kimono to the accoutrement of the Imperial family. Ceremonial clothing is often richly decorated and offers little protection.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.K61XHG9GnFLieqjc","armor":{"physical":1,"supernatural":0},"rarity":"4","zeni":"1 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000010","name":"Resplendent"}]},{"name":"Calligraphy Set","quantity":1,"description":"<p>These ornate boxes contain items a practiced callig- rapher needs to craft books, letters, scrolls, and other written communications. It consists of a small wooden box that contains a variety of brushes, inkstones, and pigments; a small bowl for water; and a small bag of sand for drying. Calligraphers and scribes customari- ly carry a calligraphy set, as so do some samurai and courtiers who prefer to write their own correspon- dence.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":242},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.MWzx5Wiu6xcCWc9J","rarity":"3","zeni":"1 bu"},{"name":"Personal Seal or Chop","quantity":1,"description":"<p>A personal chop is used by samurai to verify their iden- tity and sign documents, among other official business. Each one is a unique design that is registered with the Miya family. Using another samurai’s chop is consid- ered both an insult and a serious crime.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":243},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.UU5eQKPBQZ9ilOTF","rarity":"6","zeni":"4 bu","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"}]},{"name":"Blank Forms","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]},{"name":"Legal Primer","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]},{"name":"Hano no Ami Pillow Book","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]},{"name":"Scroll of Authority from Magistrate of Shirogome","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]}]},{"xp":80,"label":"Emerald Magistrate","rank":3,"school":"Doji Bureaucrat School","foundry_id":null,"rings":{"air":3,"earth":2,"fire":2,"water":3,"void":2},"skills":{"artisan":{"aesthetics":0,"composition":2,"design":1,"smithing":0},"martial":{"fitness":1,"melee":0,"ranged":0,"unarmed":3,"meditation":0,"tactics":0},"scholar":{"culture":2,"government":3,"medicine":0,"sentiment":2,"theology":0},"social":{"command":2,"courtesy":3,"games":0,"performance":1},"trade":{"commerce":1,"labor":0,"seafaring":0,"skulduggery":0,"survival":0}},"social":{"honor":69,"glory":71,"status":60,"ninjo":"Strictures too often interfere with a beautiful tale.\n\nShe escapes into literature, particularly pillow-books, and riding her horse, Kogorashi, a Utaku steed and wedding gift from her husband's family.","giri":"Currently, Kitsuki Kāgi, in service as an Emerald Magistrate under the Emperor.\n\nPreviously, she served Asahina Shigehiro, lord of the city of Shirogome, on issues of imperial law and legal arbitration.\n\nHer giri: Rule must bind, and if needed, contort.","bushido_tenets":{"paramount":"Courtesy","less_significant":"Courage"}},"derived":{"endurance":10,"composure":12,"focus":5,"vigilance":3,"void_points":2},"money":{"zeni":0,"koku":0,"bu":0},"advancements":[{"label":"Government +1 (1 -> 2)","type":"skill","skill":"government","ring":"void","at_rank":1,"xp":4,"in_curriculum":true},{"label":"Government +1 (2 -> 3)","type":"skill","skill":"government","ring":"void","at_rank":1,"xp":6,"in_curriculum":true},{"label":"Sentiment +1 (1 -> 2)","type":"skill","skill":"sentiment","ring":"void","at_rank":1,"xp":4,"in_curriculum":true},{"label":"Fire +1 (1 -> 2)","type":"ring","ring":"fire","at_rank":2,"xp":6,"in_curriculum":false},{"label":"Void +1 (1 -> 2)","type":"ring","ring":"void","at_rank":2,"xp":6,"in_curriculum":false},{"label":"Courtesy +1 (2 -> 3)","type":"skill","skill":"courtesy","ring":"void","at_rank":2,"xp":6,"in_curriculum":true},{"label":"Martial Arts [Unarmed] +1 (0 -> 1)","type":"skill","skill":"unarmed","ring":"void","at_rank":1,"xp":2,"in_curriculum":true,"via":"Emerald Magistrate"},{"label":"Martial Arts [Unarmed] +1 (1 -> 2)","type":"skill","skill":"unarmed","ring":"void","at_rank":1,"xp":4,"in_curriculum":true,"via":"Emerald Magistrate"},{"label":"Martial Arts [Unarmed] +1 (2 -> 3)","type":"skill","skill":"unarmed","ring":"void","at_rank":1,"xp":6,"in_curriculum":true,"via":"Emerald Magistrate"},{"label":"Performance +1 (0 -> 1)","type":"skill","skill":"performance","ring":"void","at_rank":1,"xp":2,"in_curriculum":true,"via":"Emerald Magistrate"},{"label":"Fitness +1 (0 -> 1)","type":"skill","skill":"fitness","ring":"void","at_rank":1,"xp":2,"in_curriculum":true,"via":"Emerald Magistrate"},{"label":"Commerce +1 (0 -> 1)","type":"skill","skill":"commerce","ring":"void","at_rank":1,"xp":2,"in_curriculum":true,"via":"Emerald Magistrate"}],"techniques":[{"name":"Courtier’s Resolve","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"shuji","rank":1,"description":"<ul><li>Warriors do battle with their bodies, and courtiers do battle with their minds. To maintain one’s composure while surrounded by the challenges of court, one must be able to clear and organize one’s mind, returning focus to the most vital tasks.</li><li>Once per scene as a Support action, you may spend 1 Void point to recover from strife.</li><li>Remove strife equal to your glory rank.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":222},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.KaIqecu4b1TpXZid"},{"name":"Stonewall Tactics","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"shuji","rank":1,"description":"<ul><li>The courtier makes themself impossible for the target to ignore, raising a pressing concern that must be addressed first or even physically planting themself between a rival and their allies.</li><li>When making a Social skill (Earth) or Martial skill (Earth) check targeting a character, you may spend (op) in the following way:</li><li>Earth (op)+: Increase the TN of any check the target makes that does not target you by 1 per (op) spent this way. This effect persists until the beginning of your next turn.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":216},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.edR9lIhccQ9wddX8"},{"name":"Procedure and Protocol","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"kind":"school_ability","rank":1,"description":"<p>When you cause a character to receive strife as a result of a check using a social approach, that character suffers additional strife equal to your school rank.</p>","text_source":"dsl","source":{"book":"court_of_stones","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.school-abilities-l5r-sortilege.Item.l3MWXTYlzmL4j247"},{"name":"Beware The Smallest Mouse","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"shuji","rank":1,"description":"<ul><li>Type: Shūji</li><li>Subtype: Water Shūji</li><li>Rank: 1</li><li>Activation: When you make a Social skill (Water) check targeting one or more characters</li><li>Opportunities: Water (op)(op)+: While interacting with you, the target treats their vigilance as 1 lower per (op)(op) spent and decreases TN of social checks targeting you by 1. Persists until end of scene.</li></ul>","text_source":"dsl","source":{"book":"court_of_stones","page":118},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.6RjitPKJypourgTx"},{"name":"Treaty Signing","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"ritual","rank":2,"description":"<ul><li>Type: Ritual</li><li>Rank: 2</li><li>Activation: Once per game session as a downtime activity</li><li>Check: TN 2 Composition (Fire) to write agreement, then TN 3 Government (Air) targeting participants</li><li>If you succeed, agreement has no loopholes. Each participant stakes 10 honor on upholding the agreement. Anyone who later breaks it loses staked honor unless another participant broke it first.</li><li>Opportunities: (op)+: All participants stake 1 additional honor plus 1 per (op) spent. (op)(op)(op): If you succeed, you need only stake half the honor other participants stake.</li></ul>","text_source":"dsl","source":{"book":"court_of_stones","page":116},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-rituals-l5r-sortilege.Item.8crnCQbpwgQyk2Ry","skill":"composition"},{"name":"Civility Foremost","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"shuji","rank":2,"description":"<ul><li>Samurai are warriors, but there are many contexts in which violence is inappropriate. Many strictures exist around the times weapons can and cannot be drawn. A courtier who has memorized the rules of such engagements can articulate why fighting would be improper or profane in nearly any situation.</li><li>As a Scheme action, make a Command or Courtesy (Earth) check targeting one character to claim protection for an individual of your choice by rights of honor. The TN of the check is equal to the target&#x27;s vigilance.</li><li>If you succeed, the target must forfeit honor equal to your Earth Ring plus your bonus successes and suffer that much strife to perform an Attack or Scheme action targeting the chosen individual. This effect persists until the end of the scene, or until the target performs an Attack or Scheme action.</li><li>Earth (op)+: Choose one additional target with vigilance lower than or equal to your first target&#x27;s vigilance per (op) spent this way.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":216},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.qCWzsCP48rEbiZ59","skill":"command,courtesy"},{"name":"Well of Desire","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"shuji","rank":1,"description":"<ul><li>Bribery is considered to be corruption in Rokugan, yet gift exchanges and gift giving is a time-honored tradition. The shrewdest courtiers can engineer scenarios in which their targets cannot refuse their gifts without tarnishing their reputations. Thus, the recipient of such a poisoned gift might find it preferable to owe the courtier a favor than to be shamed in public.</li><li>When you make a Courtesy (Water) check to present a gift to a target, you may spend (op) as follows:</li><li>Water (op): To refuse your gift, your target must forfeit glory equal to your Water Ring. Additionally, if the gift is something that the target desires, the target also must suffer strife equal to its rarity to refuse it. If your target accepts the gift, reduce the TN of your next Social skill check targeting them by the rarity of the item (to a minimum of 1).</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":221},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.DE7tPCTvvSVptjRj"},{"name":"The Wind Blows Both Ways","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"shuji","rank":3,"description":"<ul><li>A word in the right ear at the right time can enhance the accomplishment of another, or a cutting slight can diminish their success in the eyes of those who matter.</li><li>When you make a Courtesy or Performance (Air) check targeting another character, you may spend (op) in the following ways:</li><li>Air (op)+: The next time the target receives a glory award, increase the glory they gain by 1 per (op) spent this way. This effect persists until the end of the scene.</li><li>Air (op)+: The next time the target forfeits or stakes glory, increase the glory they must forfeit or stake by 1 per (op) spent this way. This effect persists until the end of the scene.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":215},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.gA96njIZ1sRcveWQ"},{"name":"Call to Ride","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"shuji","rank":1,"description":"<ul><li>Activation: As a Support action, you can make a TN 1 Survival (Water) check targeting your mount or animal companion, provided it is within range 5 of you.</li><li>If you succeed, your mount or animal companion immediately moves up to 2 range bands toward you, plus 1 additional per two bonus successes. If it is a mount and ends at range 0, you can immediately mount it.</li><li>Opportunities: (op)(op): Increase TN of Attack action checks targeting you and your mount/companion by 1 until end of your next turn. (op)(op): If you perform a Maneuver action after mounting, you may move up to 2 range bands instead of 1.</li></ul>","text_source":"dsl","source":{"book":"children_of_the_five_winds","page":115},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.hk3fDtNibUKG9BOJ","skill":"survival"},{"name":"Crescent Moon Style","via":"Emerald Magistrate","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"kata","rank":2,"description":"<ul><li>Striking first is valuable, but so is surviving. To defend without sacrificing offense, a bushi must be ready to retaliate swiftly after blocking or evading. With a quick shift, the bushi switches from defense to bring down their full force upon their enemy.</li><li>When you perform Guard action, you may spend (op):</li><li>(op): After a character at range 1-2 performs an Attack action targeting you or another character you are guarding, you may perform a Strike action with one readied Martial Arts [Melee or Unarmed] weapon targeting that character (if within weapon&#x27;s range). Persists until start of your next turn, or until you perform a Strike action this way.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":175},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.skeRFViU7iirdPkB"},{"name":"Coiling Serpent Style","via":"Emerald Magistrate","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"kata","rank":2,"description":"<ul><li>Entrapping techniques can be performed with many different weapons, from the kusari-gama wielded by brigands to the ornate, hook-headed polearms used by the Phoenix Clan’s greatest masters of the spear.</li><li>When you make a Martial Arts [Melee] or Martial Arts [Unarmed] check using a Snaring weapon, you may spend (op):</li><li>+(op): Choose one weapon a target has readied; that weapon cannot be used for Attack actions. Persists until end of your next turn.</li><li>(op) +(op): One target of your action per (op) spent this way becomes Immobilized.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":179},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.ik5iXghoLDyeN2Ml"},{"name":"Open-Hand Style","via":"Emerald Magistrate","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"kata","rank":2,"description":"<ul><li>Power does not come from speed alone. A master martial artist can apply force for maximum effect, making even gentle movements devastatingly effective blocks and strikes. With enough experience, a martial artist can even control their opponent’s stance.</li><li>When you make a Martial Arts [Unarmed] check using a weapon with the Snaring quality, you may spend (op):</li><li>(op) +(op): One target per (op) spent this way must switch to a different stance of your choice. Targets of Silhouette 3 or greater may resist with a TN 3 Fitness check and ignore this effect if they succeed.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":180},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.skdBwRFHDheXzg5v"},{"name":"Shallow Waters","via":"Emerald Magistrate","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"shuji","rank":1,"description":"<ul><li>A good courtier learns how to read the desires of those around them from the subtle cues of their responses in conversation, as well as how to probe for details without revealing their intentions.</li><li>When you make a Social skill (Water) check targeting a character, you may spend (op) as follows:</li><li>Water (op): Learn of one material item or worldly experience the target desires.</li><li>Water (op)(op): Learn the target&#x27;s Ninjō.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":220},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.S4OASGrJcnGMYvIP"}],"peculiarities":[{"name":"Scorn of [One Group]","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"water","types":"Interpersonal","description":"<ul><li>You have earned the ire of a particular group, which has seriously damaged your ability to work with its members or enlist their help. You have been barred from entering their facilities, and they refuse to meet or communicate with you directly. Confer with the GM to select a campaign-appropriate group when choosing this disadvantage.</li><li>When performing a check to interact with the chosen group that relies on your rapport with its members (such as a Courtesy [Water] check to persuade them to do something or a Performance [Water] check to impress a group of them), you must choose and reroll two dice containing success or explosive success. After resolving the check, if you failed, you gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":127},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.phzQyXvNxw7HVrgQ"},{"name":"Wordplay","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"passion","ring":"air","types":"Interpersonal, Mental","description":"<ul><li>You can always identify rhetorical and literary patterns in the works of others when reading or listening to them.</li><li>After performing a check to interpret or create a play on words (such as a Composition [Air] check to write a poem with a perfectly executed poetic pun or a Performance [Air] check to subtly imply something to your audience via a double meaning), you remove 3 strife.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":116},"uuid":"Compendium.l5r5e-compendia-sortilege.passions-l5r-sortilege.Item.QPLHN6JrL4Jshp4P"},{"name":"Fear of Death","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"anxiety","ring":"earth","types":"Mental, Physical","description":"<ul><li>You cannot voluntarily choose to die or sacrifice your life (including committing seppuku when honor demands it), and if there is a chance you could live, you must always pursue it.</li><li>After performing a check to risk your life or accept your mortality (such as a Meditation [Earth] check to find inner tranquility before battle or a Tactics [Earth] check to hold a position against long odds), you receive 3 strife. If this is the first time this has occurred this scene, gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":132},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.mjsfXGRv9ip0vn9n"},{"name":"Haunting","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"void","types":"Interpersonal, Spiritual","description":"<ul><li>The spirit has their own agenda (determined by the GM), which interferes with yours at inopportune times.</li><li>When you make a check to defy the will of the spirit haunting you (such as a Meditation [Void] check to find solace in meditation or a Skulduggery [Void] check to perform disreputable acts to survive), you must choose and reroll two dice containing success or explosive success. After resolving the check, if you failed, you gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":122},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.kc6gGspWMQATYqIO"},{"name":"Blessed Lineage","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"void","types":"Interpersonal, Spiritual","description":"<ul><li>Characters with status of 50 or higher understand that they might suffer a loss of prestige if they harm you, and thus do not choose to kill you as their first option, even if you are a political obstacle they would otherwise eliminate without hesitation.</li><li>When performing a check for which your esteemed lineage is a benefit (such as a Command [Void] check to challenge someone&#x27;s perception of a situation or a Government [Void] check to know the likelihood of a political eventuality), you may reroll up to two dice.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":103},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.tRfoACKusbLsicmy"},{"name":"Paragon of Courtesy","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"air","types":"Mental, Virtue","description":"<ul><li>Pick One: Compassion (Water), Courage (Fire), Courtesy (Air), Duty and Loyalty (Earth), Honor (Void), Righteousness (Void), Sincerity (Void). A character may have multiple instances of this advantage for different tenets. Each tenet counts as a separate advantage. You believe utterly in the chosen Bushidō tenet, and others instinctively discern that your actions are genuine when you act in accordance with it.</li><li>When performing a check for which you need to convince others of, or leverage your faith in, the Bushidō tenet (such as a Performance check to recount a tale that impresses its importance upon others or a Martial Arts [Melee] check to take up arms for this cause), you may reroll up to two dice.</li></ul>","text_source":"dsl","text_via":"Paragon of a Bushidō Tenet","source":{"book":"core_rulebook","page":108},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.fCqRyrkg6meX21xR"},{"name":"Dark Secret","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":2,"kind":"anxiety","ring":"void","types":"Interpersonal","description":"<ul><li>You have a dark secret that, if exposed, could bring ruin upon your house and disgrace your ancestors and descendants alike. If the details of this secret become public, your glory value decreases dramatically, as if you had lost staked glory (by 10 to 20). Depending on the secret, your status value might also decrease considerably (by 5 to 10), as if you had lost staked status.</li><li>After performing a check to assert your will over yourself or others (such as a Command [Void] check to order troops to fight to the bitter end or a Meditation [Void] check to find inner peace), you receive 3 strife. If this is the first time this has occurred this scene, gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":132},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.bd12LEtxVlmVVckt"},{"name":"Famously Successful","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":2,"kind":"distinction","ring":"fire","types":"Fame, Interpersonal","description":"<ul><li>Other people have heard of you for your ability to get results at any cost, and they believe it by default unless given evidence to the contrary.</li><li>When performing a check for which you need to leverage your reputation for efficiency (such as a Courtesy [Fire] check to convince your lord to give you a position or a Tactics [Fire] check to get enemy troops to withdraw in the face of a show of force), you may reroll up to two dice.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":105},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.ITdK6Jhu73A3rXPx"},{"name":"Legal Scholarship","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":3,"kind":"distinction","ring":"air","types":"Interpersonal, Social","description":"<ul><li>Your family possesses old legal documents from Rokugani, Qamarist, and other legal traditions.</li><li>When performing a check to interact with a legal body or using a legal code, you may reroll up to two dice.</li></ul>","text_source":"dsl","source":{"book":"children_of_the_five_winds","page":93},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.BB7QfDAYqyo65Kap"},{"name":"Paragon of Courage","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":3,"kind":"distinction","ring":"fire","types":"Mental, Virtue","description":"<ul><li>Pick One: Compassion (Water), Courage (Fire), Courtesy (Air), Duty and Loyalty (Earth), Honor (Void), Righteousness (Void), Sincerity (Void). A character may have multiple instances of this advantage for different tenets. Each tenet counts as a separate advantage. You believe utterly in the chosen Bushidō tenet, and others instinctively discern that your actions are genuine when you act in accordance with it.</li><li>When performing a check for which you need to convince others of, or leverage your faith in, the Bushidō tenet (such as a Performance check to recount a tale that impresses its importance upon others or a Martial Arts [Melee] check to take up arms for this cause), you may reroll up to two dice.</li></ul>","text_source":"dsl","text_via":"Paragon of a Bushidō Tenet","source":{"book":"core_rulebook","page":108},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.trppadBbshGjbSP2"}],"titles":[{"name":"Emerald Magistrate","xp_used":30,"xp_cost":30,"in_curriculum":false,"bought_at_rank":2,"description":"<p>The Emerald Champion, the Emperor, and other high-ranking officials in the office of the Emerald Champion can appoint Emerald Magistrates, and do so when a samurai proves worthy of the post or when the need arises for more arbiters of the Emperor&#x27;s Justice.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":305},"uuid":"Compendium.l5r5e-compendia-sortilege.titles-l5r-sortilege.Item.wJaOsQLVZi3JQrmy"}],"bonds":[{"name":"Shinjo Harunobu","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"custom":true,"description":"<p><span class=\"fontstyle0\">Samurai are expected to place romantic love below their obligations to family and clan—but the human heart is not so easily confined. Many samurai who fall in love keep their relationship secret, while others are more overt. The following are suggested narrative effects for a character with a Lover bond:</span></p><ul><li><p><span class=\"fontstyle0\">- A lover seeks to spend time with you, writes letters to you, and is willing to assist you in ways that do not require publicly acknowledging your bond (giving you information key to pursuing a desired goal, encouraging you to pursue your personal interests, helping you to deal with emotions you usually must keep to yourself), and they expect you to do the same.</span></p></li><li><p><span class=\"fontstyle0\">Generally, your lover’s allies do not acknowledge your relationship. Some might be favorably disposed to you covertly if you make their ally happy (and unfavorably disposed if you make them unhappy), while others might be jealous of the attention you receive. Your lover’s enemies might target you to attempt to gain leverage over your lover.</span></p></li><li><p><span class=\"fontstyle0\">If your bond rank is 3 or higher, a lover is more overt about your relationship, allowing them to assist you more publicly (such as giving you letters of introduction to officials above your status, allowing you to use their name to pursue your goals, and even helping you directly), and they expect the same from you.</span></p></li></ul><p></p><p><span class=\"fontstyle3\"><strong>Bond Ability:</strong> With You, the Storm Subsides</span></p>","source_reference":{"source":"","page":0}}],"signature_scrolls":[{"name":"Voice of Authority (Emerald Magistrate)","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":2,"description":"<p>Once per game session when making a Scheme or Support action check using a Social skill, you may choose additional targets equal to your Glory rank. You cannot choose any additional target with vigilance higher than the highest among your initial targets.</p>","text_source":"dsl","source":{"book":null,"page":0},"uuid":"Compendium.l5r5e-compendia-sortilege.title-abilities-l5r-sortilege.Item.HfduRsNksc7HGSNm"}],"gear":[{"name":"Wakizashi","quantity":1,"description":"<p>Whereas the katana represents a samurai’s status as a warrior, the wakizashi represents their place in Rokugan’s social order and strict caste system. The wakizashi is a small, katana-like sword usually two to three feet in length, with the same flexible blade and lethal edge. It is often made as part of a pair, with the same decorations as its matched katana. The wakizashi also fills another role: it clearly signals that its wearer is a samurai, and a person of honor who will make the ultimate sacrifice for their ideals and their master. It is the tool with which a samurai commits seppuku: ritual suicide, the last protest of an aggrieved and honorable samurai.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":233},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.S1MG4qPHEV3N8XnO","damage":3,"deadliness":5,"range":"0-1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"15 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Ceremonial Clothes","quantity":1,"description":"<p>Ceremonial clothing is any garment worn during an official ceremony, from a samurai’s court kimono to the accoutrement of the Imperial family. Ceremonial clothing is often richly decorated and offers little protection.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.K61XHG9GnFLieqjc","armor":{"physical":1,"supernatural":0},"rarity":"4","zeni":"1 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000010","name":"Resplendent"}]},{"name":"Calligraphy Set","quantity":1,"description":"<p>These ornate boxes contain items a practiced callig- rapher needs to craft books, letters, scrolls, and other written communications. It consists of a small wooden box that contains a variety of brushes, inkstones, and pigments; a small bowl for water; and a small bag of sand for drying. Calligraphers and scribes customari- ly carry a calligraphy set, as so do some samurai and courtiers who prefer to write their own correspon- dence.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":242},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.MWzx5Wiu6xcCWc9J","rarity":"3","zeni":"1 bu"},{"name":"Personal Seal or Chop","quantity":1,"description":"<p>A personal chop is used by samurai to verify their iden- tity and sign documents, among other official business. Each one is a unique design that is registered with the Miya family. Using another samurai’s chop is consid- ered both an insult and a serious crime.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":243},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.UU5eQKPBQZ9ilOTF","rarity":"6","zeni":"4 bu","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"}]},{"name":"Blank Forms","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]},{"name":"Legal Primer","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]},{"name":"Hano no Ami Pillow Book","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]},{"name":"Scroll of Authority from Magistrate of Shirogome","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]}]},{"xp":100,"label":"Current","rank":3,"school":"Doji Bureaucrat School","foundry_id":"Q9Nd6vhG4PMG0aXZ","rings":{"air":3,"earth":3,"fire":2,"water":3,"void":2},"skills":{"artisan":{"aesthetics":0,"composition":2,"design":1,"smithing":0},"martial":{"fitness":1,"melee":0,"ranged":0,"unarmed":3,"meditation":0,"tactics":0},"scholar":{"culture":2,"government":3,"medicine":0,"sentiment":2,"theology":0},"social":{"command":3,"courtesy":3,"games":0,"performance":1},"trade":{"commerce":1,"labor":0,"seafaring":0,"skulduggery":0,"survival":0}},"social":{"honor":69,"glory":71,"status":60,"ninjo":"Strictures too often interfere with a beautiful tale.\n\nShe escapes into literature, particularly pillow-books, and riding her horse, Kogorashi, a Utaku steed and wedding gift from her husband's family.","giri":"Currently, Kitsuki Kāgi, in service as an Emerald Magistrate under the Emperor.\n\nPreviously, she served Asahina Shigehiro, lord of the city of Shirogome, on issues of imperial law and legal arbitration.\n\nHer giri: Rule must bind, and if needed, contort.","bushido_tenets":{"paramount":"Courtesy","less_significant":"Courage"}},"derived":{"endurance":10,"composure":12,"focus":5,"vigilance":3,"void_points":2},"money":{"zeni":0,"koku":0,"bu":0},"advancements":[{"label":"Government +1 (1 -> 2)","type":"skill","skill":"government","ring":"void","at_rank":1,"xp":4,"in_curriculum":true},{"label":"Government +1 (2 -> 3)","type":"skill","skill":"government","ring":"void","at_rank":1,"xp":6,"in_curriculum":true},{"label":"Sentiment +1 (1 -> 2)","type":"skill","skill":"sentiment","ring":"void","at_rank":1,"xp":4,"in_curriculum":true},{"label":"Fire +1 (1 -> 2)","type":"ring","ring":"fire","at_rank":2,"xp":6,"in_curriculum":false},{"label":"Void +1 (1 -> 2)","type":"ring","ring":"void","at_rank":2,"xp":6,"in_curriculum":false},{"label":"Martial Arts [Unarmed] +1 (0 -> 1)","type":"skill","skill":"unarmed","ring":"void","at_rank":1,"xp":2,"in_curriculum":true,"via":"Emerald Magistrate"},{"label":"Martial Arts [Unarmed] +1 (1 -> 2)","type":"skill","skill":"unarmed","ring":"void","at_rank":1,"xp":4,"in_curriculum":true,"via":"Emerald Magistrate"},{"label":"Martial Arts [Unarmed] +1 (2 -> 3)","type":"skill","skill":"unarmed","ring":"void","at_rank":1,"xp":6,"in_curriculum":true,"via":"Emerald Magistrate"},{"label":"Performance +1 (0 -> 1)","type":"skill","skill":"performance","ring":"void","at_rank":1,"xp":2,"in_curriculum":true,"via":"Emerald Magistrate"},{"label":"Fitness +1 (0 -> 1)","type":"skill","skill":"fitness","ring":"void","at_rank":1,"xp":2,"in_curriculum":true,"via":"Emerald Magistrate"},{"label":"Commerce +1 (0 -> 1)","type":"skill","skill":"commerce","ring":"void","at_rank":1,"xp":2,"in_curriculum":true,"via":"Emerald Magistrate"},{"label":"Courtesy +1 (2 -> 3)","type":"skill","skill":"courtesy","ring":"void","at_rank":2,"xp":6,"in_curriculum":true},{"label":"Earth +1 (2 -> 3)","type":"ring","ring":"earth","at_rank":1,"xp":9,"in_curriculum":false,"via":"Personal Advisor to Miya Misato"},{"label":"Command +1 (2 -> 3)","type":"skill","skill":"command","ring":"void","at_rank":3,"xp":6,"in_curriculum":true}],"techniques":[{"name":"Courtier’s Resolve","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"shuji","rank":1,"description":"<ul><li>Warriors do battle with their bodies, and courtiers do battle with their minds. To maintain one’s composure while surrounded by the challenges of court, one must be able to clear and organize one’s mind, returning focus to the most vital tasks.</li><li>Once per scene as a Support action, you may spend 1 Void point to recover from strife.</li><li>Remove strife equal to your glory rank.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":222},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.KaIqecu4b1TpXZid"},{"name":"Stonewall Tactics","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"shuji","rank":1,"description":"<ul><li>The courtier makes themself impossible for the target to ignore, raising a pressing concern that must be addressed first or even physically planting themself between a rival and their allies.</li><li>When making a Social skill (Earth) or Martial skill (Earth) check targeting a character, you may spend (op) in the following way:</li><li>Earth (op)+: Increase the TN of any check the target makes that does not target you by 1 per (op) spent this way. This effect persists until the beginning of your next turn.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":216},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.edR9lIhccQ9wddX8"},{"name":"Procedure and Protocol","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"kind":"school_ability","rank":1,"description":"<p>When you cause a character to receive strife as a result of a check using a social approach, that character suffers additional strife equal to your school rank.</p>","text_source":"dsl","source":{"book":"court_of_stones","page":91},"uuid":"Compendium.l5r5e-compendia-sortilege.school-abilities-l5r-sortilege.Item.l3MWXTYlzmL4j247"},{"name":"Beware The Smallest Mouse","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"shuji","rank":1,"description":"<ul><li>Type: Shūji</li><li>Subtype: Water Shūji</li><li>Rank: 1</li><li>Activation: When you make a Social skill (Water) check targeting one or more characters</li><li>Opportunities: Water (op)(op)+: While interacting with you, the target treats their vigilance as 1 lower per (op)(op) spent and decreases TN of social checks targeting you by 1. Persists until end of scene.</li></ul>","text_source":"dsl","source":{"book":"court_of_stones","page":118},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.6RjitPKJypourgTx"},{"name":"Treaty Signing","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":1,"kind":"ritual","rank":2,"description":"<ul><li>Type: Ritual</li><li>Rank: 2</li><li>Activation: Once per game session as a downtime activity</li><li>Check: TN 2 Composition (Fire) to write agreement, then TN 3 Government (Air) targeting participants</li><li>If you succeed, agreement has no loopholes. Each participant stakes 10 honor on upholding the agreement. Anyone who later breaks it loses staked honor unless another participant broke it first.</li><li>Opportunities: (op)+: All participants stake 1 additional honor plus 1 per (op) spent. (op)(op)(op): If you succeed, you need only stake half the honor other participants stake.</li></ul>","text_source":"dsl","source":{"book":"court_of_stones","page":116},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-rituals-l5r-sortilege.Item.8crnCQbpwgQyk2Ry","skill":"composition"},{"name":"Civility Foremost","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"shuji","rank":2,"description":"<ul><li>Samurai are warriors, but there are many contexts in which violence is inappropriate. Many strictures exist around the times weapons can and cannot be drawn. A courtier who has memorized the rules of such engagements can articulate why fighting would be improper or profane in nearly any situation.</li><li>As a Scheme action, make a Command or Courtesy (Earth) check targeting one character to claim protection for an individual of your choice by rights of honor. The TN of the check is equal to the target&#x27;s vigilance.</li><li>If you succeed, the target must forfeit honor equal to your Earth Ring plus your bonus successes and suffer that much strife to perform an Attack or Scheme action targeting the chosen individual. This effect persists until the end of the scene, or until the target performs an Attack or Scheme action.</li><li>Earth (op)+: Choose one additional target with vigilance lower than or equal to your first target&#x27;s vigilance per (op) spent this way.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":216},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.qCWzsCP48rEbiZ59","skill":"command,courtesy"},{"name":"Well of Desire","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"shuji","rank":1,"description":"<ul><li>Bribery is considered to be corruption in Rokugan, yet gift exchanges and gift giving is a time-honored tradition. The shrewdest courtiers can engineer scenarios in which their targets cannot refuse their gifts without tarnishing their reputations. Thus, the recipient of such a poisoned gift might find it preferable to owe the courtier a favor than to be shamed in public.</li><li>When you make a Courtesy (Water) check to present a gift to a target, you may spend (op) as follows:</li><li>Water (op): To refuse your gift, your target must forfeit glory equal to your Water Ring. Additionally, if the gift is something that the target desires, the target also must suffer strife equal to its rarity to refuse it. If your target accepts the gift, reduce the TN of your next Social skill check targeting them by the rarity of the item (to a minimum of 1).</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":221},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.DE7tPCTvvSVptjRj"},{"name":"The Wind Blows Both Ways","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"shuji","rank":3,"description":"<ul><li>A word in the right ear at the right time can enhance the accomplishment of another, or a cutting slight can diminish their success in the eyes of those who matter.</li><li>When you make a Courtesy or Performance (Air) check targeting another character, you may spend (op) in the following ways:</li><li>Air (op)+: The next time the target receives a glory award, increase the glory they gain by 1 per (op) spent this way. This effect persists until the end of the scene.</li><li>Air (op)+: The next time the target forfeits or stakes glory, increase the glory they must forfeit or stake by 1 per (op) spent this way. This effect persists until the end of the scene.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":215},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.gA96njIZ1sRcveWQ"},{"name":"Crescent Moon Style","via":"Emerald Magistrate","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"kata","rank":2,"description":"<ul><li>Striking first is valuable, but so is surviving. To defend without sacrificing offense, a bushi must be ready to retaliate swiftly after blocking or evading. With a quick shift, the bushi switches from defense to bring down their full force upon their enemy.</li><li>When you perform Guard action, you may spend (op):</li><li>(op): After a character at range 1-2 performs an Attack action targeting you or another character you are guarding, you may perform a Strike action with one readied Martial Arts [Melee or Unarmed] weapon targeting that character (if within weapon&#x27;s range). Persists until start of your next turn, or until you perform a Strike action this way.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":175},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.skeRFViU7iirdPkB"},{"name":"Coiling Serpent Style","via":"Emerald Magistrate","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"kata","rank":2,"description":"<ul><li>Entrapping techniques can be performed with many different weapons, from the kusari-gama wielded by brigands to the ornate, hook-headed polearms used by the Phoenix Clan’s greatest masters of the spear.</li><li>When you make a Martial Arts [Melee] or Martial Arts [Unarmed] check using a Snaring weapon, you may spend (op):</li><li>+(op): Choose one weapon a target has readied; that weapon cannot be used for Attack actions. Persists until end of your next turn.</li><li>(op) +(op): One target of your action per (op) spent this way becomes Immobilized.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":179},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.ik5iXghoLDyeN2Ml"},{"name":"Open-Hand Style","via":"Emerald Magistrate","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"kata","rank":2,"description":"<ul><li>Power does not come from speed alone. A master martial artist can apply force for maximum effect, making even gentle movements devastatingly effective blocks and strikes. With enough experience, a martial artist can even control their opponent’s stance.</li><li>When you make a Martial Arts [Unarmed] check using a weapon with the Snaring quality, you may spend (op):</li><li>(op) +(op): One target per (op) spent this way must switch to a different stance of your choice. Targets of Silhouette 3 or greater may resist with a TN 3 Fitness check and ignore this effect if they succeed.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":180},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-kata-l5r-sortilege.Item.skdBwRFHDheXzg5v"},{"name":"Shallow Waters","via":"Emerald Magistrate","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":0,"kind":"shuji","rank":1,"description":"<ul><li>A good courtier learns how to read the desires of those around them from the subtle cues of their responses in conversation, as well as how to probe for details without revealing their intentions.</li><li>When you make a Social skill (Water) check targeting a character, you may spend (op) as follows:</li><li>Water (op): Learn of one material item or worldly experience the target desires.</li><li>Water (op)(op): Learn the target&#x27;s Ninjō.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":220},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.S4OASGrJcnGMYvIP"},{"name":"Call to Ride","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":2,"kind":"shuji","rank":1,"description":"<ul><li>Activation: As a Support action, you can make a TN 1 Survival (Water) check targeting your mount or animal companion, provided it is within range 5 of you.</li><li>If you succeed, your mount or animal companion immediately moves up to 2 range bands toward you, plus 1 additional per two bonus successes. If it is a mount and ends at range 0, you can immediately mount it.</li><li>Opportunities: (op)(op): Increase TN of Attack action checks targeting you and your mount/companion by 1 until end of your next turn. (op)(op): If you perform a Maneuver action after mounting, you may move up to 2 range bands instead of 1.</li></ul>","text_source":"dsl","source":{"book":"children_of_the_five_winds","page":115},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.hk3fDtNibUKG9BOJ","skill":"survival"},{"name":"Hidden in Smoke","xp_used":3,"xp_cost":3,"in_curriculum":true,"bought_at_rank":3,"kind":"shuji","rank":4,"description":"<ul><li>Type: Shūji</li><li>Subtype: Air Shūji</li><li>Rank: 4</li><li>Activation: Once per scene as a Scheme action</li><li>Check: Social (Air) check targeting one character. TN equals target&#x27;s vigilance.</li><li>If you succeed, hide your true goal or objective. Any ability that would reveal your true intentions reveals a false, narratively appropriate goal instead. Persists until end of scene. During intrigue, gain 1 momentum point.</li><li>Opportunities: Air (op)(op)+: Choose one additional target per (op)(op) spent. Air (op)(op)+: Gain 1 additional momentum point per (op)(op) spent.</li></ul>","text_source":"dsl","source":{"book":"court_of_stones","page":117},"uuid":"Compendium.l5r5e-compendia-sortilege.techniques-shuji-l5r-sortilege.Item.nsWla8yTNYEfyAbY","skill":"social"}],"peculiarities":[{"name":"Scorn of [One Group]","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"water","types":"Interpersonal","description":"<ul><li>You have earned the ire of a particular group, which has seriously damaged your ability to work with its members or enlist their help. You have been barred from entering their facilities, and they refuse to meet or communicate with you directly. Confer with the GM to select a campaign-appropriate group when choosing this disadvantage.</li><li>When performing a check to interact with the chosen group that relies on your rapport with its members (such as a Courtesy [Water] check to persuade them to do something or a Performance [Water] check to impress a group of them), you must choose and reroll two dice containing success or explosive success. After resolving the check, if you failed, you gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":127},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.phzQyXvNxw7HVrgQ"},{"name":"Wordplay","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"passion","ring":"air","types":"Interpersonal, Mental","description":"<ul><li>You can always identify rhetorical and literary patterns in the works of others when reading or listening to them.</li><li>After performing a check to interpret or create a play on words (such as a Composition [Air] check to write a poem with a perfectly executed poetic pun or a Performance [Air] check to subtly imply something to your audience via a double meaning), you remove 3 strife.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":116},"uuid":"Compendium.l5r5e-compendia-sortilege.passions-l5r-sortilege.Item.QPLHN6JrL4Jshp4P"},{"name":"Fear of Death","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"anxiety","ring":"earth","types":"Mental, Physical","description":"<ul><li>You cannot voluntarily choose to die or sacrifice your life (including committing seppuku when honor demands it), and if there is a chance you could live, you must always pursue it.</li><li>After performing a check to risk your life or accept your mortality (such as a Meditation [Earth] check to find inner tranquility before battle or a Tactics [Earth] check to hold a position against long odds), you receive 3 strife. If this is the first time this has occurred this scene, gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":132},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.mjsfXGRv9ip0vn9n"},{"name":"Haunting","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"adversity","ring":"void","types":"Interpersonal, Spiritual","description":"<ul><li>The spirit has their own agenda (determined by the GM), which interferes with yours at inopportune times.</li><li>When you make a check to defy the will of the spirit haunting you (such as a Meditation [Void] check to find solace in meditation or a Skulduggery [Void] check to perform disreputable acts to survive), you must choose and reroll two dice containing success or explosive success. After resolving the check, if you failed, you gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":122},"uuid":"Compendium.l5r5e-compendia-sortilege.adversities-l5r-sortilege.Item.kc6gGspWMQATYqIO"},{"name":"Blessed Lineage","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"void","types":"Interpersonal, Spiritual","description":"<ul><li>Characters with status of 50 or higher understand that they might suffer a loss of prestige if they harm you, and thus do not choose to kill you as their first option, even if you are a political obstacle they would otherwise eliminate without hesitation.</li><li>When performing a check for which your esteemed lineage is a benefit (such as a Command [Void] check to challenge someone&#x27;s perception of a situation or a Government [Void] check to know the likelihood of a political eventuality), you may reroll up to two dice.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":103},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.tRfoACKusbLsicmy"},{"name":"Paragon of Courtesy","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":0,"kind":"distinction","ring":"air","types":"Mental, Virtue","description":"<ul><li>Pick One: Compassion (Water), Courage (Fire), Courtesy (Air), Duty and Loyalty (Earth), Honor (Void), Righteousness (Void), Sincerity (Void). A character may have multiple instances of this advantage for different tenets. Each tenet counts as a separate advantage. You believe utterly in the chosen Bushidō tenet, and others instinctively discern that your actions are genuine when you act in accordance with it.</li><li>When performing a check for which you need to convince others of, or leverage your faith in, the Bushidō tenet (such as a Performance check to recount a tale that impresses its importance upon others or a Martial Arts [Melee] check to take up arms for this cause), you may reroll up to two dice.</li></ul>","text_source":"dsl","text_via":"Paragon of a Bushidō Tenet","source":{"book":"core_rulebook","page":108},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.fCqRyrkg6meX21xR"},{"name":"Dark Secret","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":2,"kind":"anxiety","ring":"void","types":"Interpersonal","description":"<ul><li>You have a dark secret that, if exposed, could bring ruin upon your house and disgrace your ancestors and descendants alike. If the details of this secret become public, your glory value decreases dramatically, as if you had lost staked glory (by 10 to 20). Depending on the secret, your status value might also decrease considerably (by 5 to 10), as if you had lost staked status.</li><li>After performing a check to assert your will over yourself or others (such as a Command [Void] check to order troops to fight to the bitter end or a Meditation [Void] check to find inner peace), you receive 3 strife. If this is the first time this has occurred this scene, gain 1 Void point.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":132},"uuid":"Compendium.l5r5e-compendia-sortilege.anxieties-l5r-sortilege.Item.bd12LEtxVlmVVckt"},{"name":"Famously Successful","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":2,"kind":"distinction","ring":"fire","types":"Fame, Interpersonal","description":"<ul><li>Other people have heard of you for your ability to get results at any cost, and they believe it by default unless given evidence to the contrary.</li><li>When performing a check for which you need to leverage your reputation for efficiency (such as a Courtesy [Fire] check to convince your lord to give you a position or a Tactics [Fire] check to get enemy troops to withdraw in the face of a show of force), you may reroll up to two dice.</li></ul>","text_source":"dsl","source":{"book":"core_rulebook","page":105},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.ITdK6Jhu73A3rXPx"},{"name":"Legal Scholarship","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":3,"kind":"distinction","ring":"air","types":"Interpersonal, Social","description":"<ul><li>Your family possesses old legal documents from Rokugani, Qamarist, and other legal traditions.</li><li>When performing a check to interact with a legal body or using a legal code, you may reroll up to two dice.</li></ul>","text_source":"dsl","source":{"book":"children_of_the_five_winds","page":93},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.BB7QfDAYqyo65Kap"},{"name":"Paragon of Courage","xp_used":0,"xp_cost":3,"in_curriculum":false,"bought_at_rank":3,"kind":"distinction","ring":"fire","types":"Mental, Virtue","description":"<ul><li>Pick One: Compassion (Water), Courage (Fire), Courtesy (Air), Duty and Loyalty (Earth), Honor (Void), Righteousness (Void), Sincerity (Void). A character may have multiple instances of this advantage for different tenets. Each tenet counts as a separate advantage. You believe utterly in the chosen Bushidō tenet, and others instinctively discern that your actions are genuine when you act in accordance with it.</li><li>When performing a check for which you need to convince others of, or leverage your faith in, the Bushidō tenet (such as a Performance check to recount a tale that impresses its importance upon others or a Martial Arts [Melee] check to take up arms for this cause), you may reroll up to two dice.</li></ul>","text_source":"dsl","text_via":"Paragon of a Bushidō Tenet","source":{"book":"core_rulebook","page":108},"uuid":"Compendium.l5r5e-compendia-sortilege.distinctions-l5r-sortilege.Item.trppadBbshGjbSP2"}],"titles":[{"name":"Emerald Magistrate","xp_used":30,"xp_cost":30,"in_curriculum":false,"bought_at_rank":2,"description":"<p>The Emerald Champion, the Emperor, and other high-ranking officials in the office of the Emerald Champion can appoint Emerald Magistrates, and do so when a samurai proves worthy of the post or when the need arises for more arbiters of the Emperor&#x27;s Justice.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":305},"uuid":"Compendium.l5r5e-compendia-sortilege.titles-l5r-sortilege.Item.wJaOsQLVZi3JQrmy"},{"name":"Personal Advisor to Miya Misato","xp_used":5,"xp_cost":36,"in_curriculum":false,"bought_at_rank":3,"custom":true,"description":"<p><span class=\"fontstyle0\">Advisors serve daimyō, Emerald Magistrates, generals, and other notables with their minds and their words, giving them guidance, ideas, and counsel as requested. A great leader must have access to far more information than any one person can reasonably know, and therefore they employ various specialists and experts who keep them up to speed on dozens of vital topics. As a result, many military strategies, legal precedents, and trade deals are penned by advisors in the name of the one they serve, and these people wield great power as a result.</span></p><p><span class=\"fontstyle2\"><strong>Assigned By:</strong> </span><span class=\"fontstyle0\">Daimyō, Emerald Magistrates, military leaders, high-ranking courtiers, and other individuals of import can appoint Advisors, and do so at their discretion.</span></p><p><span class=\"fontstyle2\"><strong>Status Award:</strong> </span><span class=\"fontstyle0\">+10 (to a minimum of 40)</span></p><p><span class=\"fontstyle2\"><strong>Title Ability:</strong> Skilled Attendant</span></p><h2>Curriculum</h2><table><tbody><tr><td><p>Scholar Skills</p></td><td><p>Skill Group</p></td></tr><tr><td><p>Commerce</p></td><td><p>Skill</p></td></tr><tr><td><p>Courtesy</p></td><td><p>Skill</p></td></tr><tr><td><p>Design</p></td><td><p>Skill</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-shuji.Item.L5RCoreShu000018\" data-pack=\"l5r5e.core-techniques-shuji\" data-type=\"Item\" data-id=\"L5RCoreShu000018\">(shuji) Fanning the Flames</a> (prereq)</p></td><td><p>Technique</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-shuji.Item.L5RCoreShu000008\" data-pack=\"l5r5e.core-techniques-shuji\" data-type=\"Item\" data-id=\"L5RCoreShu000008\">(shuji) Feigned Opening</a> (prereq)</p></td><td><p>Technique</p></td></tr><tr><td><p><a class=\"entity-link content-link\" draggable=\"true\" data-link=\"\" data-uuid=\"Compendium.l5r5e.core-techniques-shuji.Item.L5RCoreShu000017\" data-pack=\"l5r5e.core-techniques-shuji\" data-type=\"Item\" data-id=\"L5RCoreShu000017\">(shuji) Stonewall Tactics</a> (prereq)</p></td><td><p>Technique</p></td></tr></tbody></table>","source_reference":{"source":"emerald_empire","page":249}}],"bonds":[{"name":"Shinjo Harunobu","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":0,"custom":true,"description":"<p><span class=\"fontstyle0\">Samurai are expected to place romantic love below their obligations to family and clan—but the human heart is not so easily confined. Many samurai who fall in love keep their relationship secret, while others are more overt. The following are suggested narrative effects for a character with a Lover bond:</span></p><ul><li><p><span class=\"fontstyle0\">- A lover seeks to spend time with you, writes letters to you, and is willing to assist you in ways that do not require publicly acknowledging your bond (giving you information key to pursuing a desired goal, encouraging you to pursue your personal interests, helping you to deal with emotions you usually must keep to yourself), and they expect you to do the same.</span></p></li><li><p><span class=\"fontstyle0\">Generally, your lover’s allies do not acknowledge your relationship. Some might be favorably disposed to you covertly if you make their ally happy (and unfavorably disposed if you make them unhappy), while others might be jealous of the attention you receive. Your lover’s enemies might target you to attempt to gain leverage over your lover.</span></p></li><li><p><span class=\"fontstyle0\">If your bond rank is 3 or higher, a lover is more overt about your relationship, allowing them to assist you more publicly (such as giving you letters of introduction to officials above your status, allowing you to use their name to pursue your goals, and even helping you directly), and they expect the same from you.</span></p></li></ul><p></p><p><span class=\"fontstyle3\"><strong>Bond Ability:</strong> With You, the Storm Subsides</span></p>","source_reference":{"source":"","page":0}}],"signature_scrolls":[{"name":"Voice of Authority (Emerald Magistrate)","xp_used":0,"xp_cost":0,"in_curriculum":false,"bought_at_rank":2,"description":"<p>Once per game session when making a Scheme or Support action check using a Social skill, you may choose additional targets equal to your Glory rank. You cannot choose any additional target with vigilance higher than the highest among your initial targets.</p>","text_source":"dsl","source":{"book":null,"page":0},"uuid":"Compendium.l5r5e-compendia-sortilege.title-abilities-l5r-sortilege.Item.HfduRsNksc7HGSNm"}],"gear":[{"name":"Wakizashi","quantity":1,"description":"<p>Whereas the katana represents a samurai’s status as a warrior, the wakizashi represents their place in Rokugan’s social order and strict caste system. The wakizashi is a small, katana-like sword usually two to three feet in length, with the same flexible blade and lethal edge. It is often made as part of a pair, with the same decorations as its matched katana. The wakizashi also fills another role: it clearly signals that its wearer is a samurai, and a person of honor who will make the ultimate sacrifice for their ideals and their master. It is the tool with which a samurai commits seppuku: ritual suicide, the last protest of an aggrieved and honorable samurai.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":233},"uuid":"Compendium.l5r5e-compendia-sortilege.weapons-l5r-sortilege.Item.S1MG4qPHEV3N8XnO","damage":3,"deadliness":5,"range":"0-1","grip_2":"Deadliness +2","skill":"melee","category":"Swords","rarity":"7","zeni":"15 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000001","name":"Razor-Edged"}]},{"name":"Ceremonial Clothes","quantity":1,"description":"<p>Ceremonial clothing is any garment worn during an official ceremony, from a samurai’s court kimono to the accoutrement of the Imperial family. Ceremonial clothing is often richly decorated and offers little protection.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":239},"uuid":"Compendium.l5r5e-compendia-sortilege.armors-l5r-sortilege.Item.K61XHG9GnFLieqjc","armor":{"physical":1,"supernatural":0},"rarity":"4","zeni":"1 koku","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"},{"id":"L5RCorePro000010","name":"Resplendent"}]},{"name":"Calligraphy Set","quantity":1,"description":"<p>These ornate boxes contain items a practiced callig- rapher needs to craft books, letters, scrolls, and other written communications. It consists of a small wooden box that contains a variety of brushes, inkstones, and pigments; a small bowl for water; and a small bag of sand for drying. Calligraphers and scribes customari- ly carry a calligraphy set, as so do some samurai and courtiers who prefer to write their own correspon- dence.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":242},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.MWzx5Wiu6xcCWc9J","rarity":"3","zeni":"1 bu"},{"name":"Personal Seal or Chop","quantity":1,"description":"<p>A personal chop is used by samurai to verify their iden- tity and sign documents, among other official business. Each one is a unique design that is registered with the Miya family. Using another samurai’s chop is consid- ered both an insult and a serious crime.</p>","text_source":"dsl","source":{"book":"core_rulebook","page":243},"uuid":"Compendium.l5r5e-compendia-sortilege.items-l5r-sortilege.Item.UU5eQKPBQZ9ilOTF","rarity":"6","zeni":"4 bu","properties":[{"id":"L5RCorePro000002","name":"Ceremonial"}]},{"name":"Blank Forms","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]},{"name":"Legal Primer","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]},{"name":"Hano no Ami Pillow Book","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]},{"name":"Scroll of Authority from Magistrate of Shirogome","quantity":1,"custom":true,"description":"","source_reference":{"source":"","page":0},"rarity":"0","zeni":"0","properties":[]}]}]};
